INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-proydemte',
  'Пройдёмте',
  (SELECT id FROM "Authors" WHERE name = 'Павел Тюлькин' ORDER BY id LIMIT 1),
  'mrd3/mrd3-proydemte.jpg',
  'data:image/jpeg;base64,',
  1329,
  1186,
  'Ночью мы с друзьями возвращались домой кое с чем, и нас вдруг окликнули полицейские. Они вели под руки пьяного мужика средних лет. Тот плакал и кричал, что ни в чём не виноват. Шёл снег.',
  '[{"kind":"image","path":"mrd3/mrd3-proydemte.jpg","caption":null},{"kind":"paragraph","text":"Ночью мы с друзьями возвращались домой кое с чем, и нас вдруг окликнули полицейские. Они вели под руки пьяного мужика средних лет. Тот плакал и кричал, что ни в чём не виноват. Шёл снег."},{"kind":"paragraph","text":"Сотрудники дружелюбно подозвали нас: «Ребят, не поможете?»"},{"kind":"paragraph","text":"Несмотря на всё уважение к государству, мне не очень хотелось в это вмешиваться. Тем более сейчас. Поэтому я ответил: «Извините, но мы торопимся». Тогда один полицейский резко огрубел и вдруг крикнул: «Так, пройдёмте! Это ненадолго»."},{"kind":"paragraph","text":"Я повторил, но уже тихонько: «Извините, мы очень торопимся», а мои приятели неожиданно оказались более сознательными гражданами и шагнули навстречу Российскому правопорядку. Сказали мне: «Да давай, недолго». Так мы и наше кое-что оказались в полицейской будке. Внутри было довольно уютно. Из-за решётки слышались хриплые крики возмущения."},{"kind":"paragraph","text":"Задержали мужика за то, что он помочился в неположенном месте. Нас просили подписать бумаги о том, что он сильно пьян и находится в неадекватном состоянии. Мужик в это время кричал, что если мы хоть одну закорючку поставим, то это будет означать, что мы мусорнулись. Слышать это было очень неприятно, ведь мы понимали, что он прав, но страх перед российской полицией — чувство более сильное."},{"kind":"paragraph","text":"Мы оставили свои подписи, и тут полицейский-главарь сказал: «Ну что, ребята, так просто я вас не отпущу»."},{"kind":"paragraph","text":"Оказалось, в будку нас позвали вовсе не в качестве понятых, а потому, что одного из нас — моего приятеля Рому — подозревают в хищении трёх тонн железа. Всё дело в его зелёной куртке. Полицейскому показалось, что она очень похожа на куртку грабителя. В целом согласен, но не садить же за это в тюрьму."},{"kind":"paragraph","text":"Мы попросили разъяснений. Полицейский ответил: «Ну вот, смотрите», — и показал нам с телефона видео, где трое парней, перекинув через плечо верёвки, медленно волокли что-то по снегу вдоль железной дороги. Никто из них не был в куртке зелёного цвета."},{"kind":"paragraph","text":"Нам объяснили, что через полчаса приедет машина, которая отвезёт нас в отделение. Она приехала через три часа, но для начала нас нужно было обыскать."},{"kind":"paragraph","text":"Обыскивали не сказать чтобы тщательно (кое-что не нашли), но у второго моего приятеля обнаружили колюще-режущее оружие — циркуль. Его тут же изъяли, и больше мы его не видели. Чем Андрюхе теперь рисовать окружности — непонятно."},{"kind":"paragraph","text":"Коп, который обманом заманил нас в своё логово, попрощался. Я этому был только рад. Мы поехали в отделение."},{"kind":"paragraph","text":"Лампочки излучали тусклый свет. Мимо решёток, за которыми мирно похрапывали задержанные, нас повели в комнатку для снятия отпечатков пальцев, а потом сопроводили в кабинет на втором этаже."},{"kind":"paragraph","text":"В кабинете был один шкаф, один календарь за 2016 год, один стол, на нём компьютер, рядом со столом кресло и стул, на которых разместилось по полицейскому, а напротив, у стены, ещё пять стульев, на три из которых присели мы — подозреваемые в хищении трёх тонн железа."},{"kind":"paragraph","text":"Полицейские включили то видео, на котором была запечатлена кража, и стали смотреть то на экран, то на нас, то на экран, то на нас... Так продолжалось минуты две. Потом они переглянулись. Тот, что сидел в кресле, сказал: «Ну-ка пройдитесь от стены до стены». Мы встали, прошлись, сели. Полицейский хихикнул и сказал: «Учитесь где-то, ребят? Скоро не будете»."},{"kind":"paragraph","text":"Мои друзья начали паниковать. Есть, конечно, вероятность, что мой мозг дорисовал это воспоминание, но кажется, Рома тогда даже воскликнул: «Да ладно?!» Я же в это время был довольно спокоен, потому что не верил в происходящее, и в итоге неожиданно сам для себя сказал: «Да он прикалывается!»"},{"kind":"paragraph","text":"Повисла тишина, которая длилась на самом деле две секунды, но для меня в тот момент эти две секунды растянулись на три (я всё ещё не очень волновался)."},{"kind":"paragraph","text":"Один из полицейских нарушил молчание: «Ну что он, придурок совсем?..» Тут я уже начал переживать больше, но коп вовремя продолжил: «Видно, что не они, сколько можно?»"},{"kind":"paragraph","text":"С нами ещё мило поболтали о том, откуда мы родом и на кого учимся, оформили какие-то бумаги, и в шесть утра мы и наше кое-что были на свободе."}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
