INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-bab-ver',
  'Баб Вер',
  (SELECT id FROM "Authors" WHERE name = 'Валерий Андронов' ORDER BY id LIMIT 1),
  'mrd3/mrd3-bab-ver.jpg',
  'data:image/jpeg;base64,',
  1557,
  1186,
  'Электричка из Девяткино отходила в 12:10, и у Сергея было время зайти в рюмочную и выпить водки. Жена его этого не одобряла, но теперь это не имело ровно никакого значения. Заказал сто граммов водки, бутерброд с килькой ',
  '[{"kind":"image","path":"mrd3/mrd3-bab-ver.jpg","caption":null},{"kind":"paragraph","text":"Электричка из Девяткино отходила в 12:10, и у Сергея было время зайти в рюмочную и выпить водки. Жена его этого не одобряла, но теперь это не имело ровно никакого значения. Заказал сто граммов водки, бутерброд с килькой и кружку пива — малый джентльменский набор. Уселся среди таких же страждущих, как и он сам, за длинный и липкий деревянный стол, молча кивнув головой: мол, привет, ребята. Никто не обратил на него внимания: делом люди были заняты — похмелялись. Сергей не похмелялся: это была ежедневная процедура — приём горького, но необходимого лекарства, после которого душевная боль, с которой он жил последнее время, хоть немного отступала и притуплялась. Но не исчезала до конца, не пропадала — сидела в нём крепко и терзала, терзала и днём, и ночью."},{"kind":"paragraph","text":"В электричке Сергей заснул, и ему приснилась жена. Они ехали на велосипедах с дачи на озеро снова вместе — по песчаной, плотно утрамбованной машинами жёлтой дороге. Жена впереди, он — чуть отставая и правее. Яркое полуденное солнце золотило стволы сосен, полутени ложились на глаза, велосипеды мягко пружинили на песке и поскрипывали. Съехали с горки к озеру и, распугав уток, через песчаный пляж поехали прямо по воде, сине-серо-зелёной, к дальнему берегу, заросшему осокой и высоченными соснами. Из-под передних колёс расходились буруны, брызги летели во все стороны, и радуги вспыхивали и гасли между спиц. А потом он заметил, что невидимая глазу дорога, по которой ехала его жена, пошла как бы под горку, и её велосипед стал медленно уходить в воду, очень медленно и плавно. Жена обернулась к нему и улыбнулась, а он закричал ей, чтобы она прыгала с велосипеда, но она продолжала крутить педали, всё глубже и глубже погружаясь в воду. Он попытался соскочить со своего велосипеда, но не смог — и от бессилия только продолжал бешено жать на педали, пытаясь догнать уходившую от него жену, и кричал, кричал, кричал…"},{"kind":"paragraph","text":"— Мужчина! Мужчина! — кто-то настойчиво теребил его за плечо. — Проснитесь, мужчина!"},{"kind":"paragraph","text":"Сергей открыл глаза и увидел встревоженное лицо женщины, сидевшей напротив него. Это она его разбудила."},{"kind":"paragraph","text":"— Вам, наверное, что-то приснилось — что-то нехорошее: вы так… — женщина запнулась, подбирая слова, — страшно мычали."},{"kind":"paragraph","text":"— Да, спасибо! — он ещё не отошёл ото сна и водил очумелыми глазами по полупустому вагону. — Приснилось…"},{"kind":"paragraph","text":"Посмотрел на проносившиеся за окном пейзажи: сосны, светло-коричневым забором выстроившиеся вдоль железной дороги, берёзы и осины, встроившиеся в этот забор, и высоченные зонтики ядовитого борщевика. Лужицы озёр, полустанки с опущенными журавлями шлагбаумов, дома, домики и домищи дач, и снова сосны. Оно и неудивительно — это же Сосновское направление. Сколько раз они вместе с женой ездили этой дорогой, а вот теперь он едет один, и ничего не изменилось."},{"kind":"paragraph","text":"Сергей сказал женщине ещё раз «спасибо», встал и, закинув на плечо рюкзак, пошёл к выходу — приближалась его станция. В тамбуре достал из куртки пачку сигарет и зажигалку и, как только двери разошлись, сошёл на потрескавшийся, выщербленный асфальт перрона и с наслаждением закурил. Электричка тоскливо и пронзительно вскрикнула у него за спиной, захлопнула двери и ушла по своим железнодорожным делам. А он так и остался стоять в одиночестве на краю перрона, вдыхая запах леса, загородного воздуха и табака. Решал, как ему идти к даче — лесом или через посёлок? Докурил, растёр окурок ногой и пошёл вдоль железной дороги, постепенно забирая влево: через подлесок к хлипкому мостку через безымянный ручеёк, по тропинке, вьющейся между невысокими ещё деревцами. Поднялся в горку и вышел на одну из многочисленных улиц дачного посёлка, от магазина повернул налево и через пять минут оказался у своей дачи. Постоял у калитки, тупо глядя на древний кодовый замок, заботливо накрытый пластмассовым горлышком бутылки из-под чего-то минерального. Кода Сергей не знал — замок всегда закрывала жена, а он всегда смеялся над этим и говорил, что вора этим не остановить. Снял рюкзак, протиснулся в щель между забором и калиткой, замаскированную лапами росшей у забора ели, и пошёл к дому."},{"kind":"paragraph","text":"Этот дом начинал строить дед Сергея ещё в прошлом веке. Сначала это был маленький домик в одну комнатку с маленькой же верандой. Потом повзрослевший отец Сергея пристроил ещё две комнаты и расширил веранду. Позже старший брат Сергея надстроил второй этаж. Дом как будто бы сам по себе рос вместе с его обитателями, вместе с ними взрослел и старился. Когда одни уходили, вместо них появлялись другие: дом знал минуты скорби и радости, звучали в нём детские голоса и старческое брюзжание, собачий лай и мяуканье кошек. По утрам он просыпался под пение птиц и засыпал вечерами под бормотание телевизора. И всем без исключения дарил покой, уют и своё тепло. Сейчас дом был зелёного цвета, когда-то — синим, а одно время даже радостно-жёлтым. Сергей на ходу достал ключи, отпер входную дверь, и аура дома — хоть и родного, но пустого — прокралась к нему в сердце. Дом молчал, словно затаился в ожидании гостей: наверное, ему тоже было одиноко, и он скучал. Сергей сразу же развил бурную деятельность: сбросил рюкзак на диван, включил газ и поставил чайник греться на плиту, прошёлся по первому этажу и везде раздёрнул шторы. По скрипучей лестнице, стараясь не наступить на сломанную третью ступеньку, поднялся на второй этаж и здесь тоже распахнул все окна. Вставил в магнитолу диск Deep Purple, и, когда зазвучали пронзительные аккорды знаменитого рифа из ‘Smoke On The Water’, дом вздрогнул — открыл глаза и стал просыпаться после долгого забытья…"},{"kind":"paragraph","text":"Чайник закипел и громко свистнул, как заблудившаяся в ночи электричка. Сергей ещё немного постоял у окна на втором этаже, глядя на соседний участок, — похоже, что и там тоже кто-то появился (из трубы дома шёл дым), — и спустился вниз. Нашёл в старом и обшарпанном буфете банку кофе, кружку и сахар. Заглянул и в холодильник на всякий случай — пусто, как в колхозном амбаре. С кружкой в одной руке и пачкой сигарет в другой вышел на улицу и присел на скамеечку, примостившуюся справа от крыльца. Короткими глотками пил горячий кофе и смотрел на высоченную старую берёзу, росшую напротив дома. Скворечники, которые вешал на дерево ещё отец Сергея, совсем развалились, и скоро, судя по всему, осыплются трухой на землю. Отец рассказывал ему, что раньше, когда дед только получил этот участок, на нём росло очень много берёз. По мере строительства дома дед валил берёзы на дрова, и сейчас их осталось всего лишь две."},{"kind":"paragraph","text":"Сергей закурил, откинулся спиной на стену дома, и это будничное движение неожиданно напомнило ему одну так до конца и не понятую историю."},{"kind":"paragraph","text":"Они с женой частенько сиживали на этой скамеечке: Сергей обычно обнимал жену за плечи, она прижималась к нему — так и сидели, греясь на солнышке. И однажды прилетела птица, да где там птица, так — птичка. Маленькая, серенькая. И зависла в воздухе примерно в метре, прямо напротив их лиц. Поражённые этим дивом, они с женой замерли, а птичка висела в воздухе, трепеща крыльями, и внимательно разглядывала их, как-то механически поворачивая малюсенькую головку то в одну, то в другую сторону. Как бы спрашивая: «Вы кто? Вы здесь зачем?» Потом сорвалась и упорхнула в сторону, но тут же вернулась и снова зависла, рассматривая их по очереди то одним, то другим глазом. Повисела, посмотрела, и они на неё успели налюбоваться, а потом полетела куда-то дальше. То, что колибри умеют так делать, Сергей с женой знали, но чтобы местные птицы были способны на подобное… чудеса!"},{"kind":"paragraph","text":"Сергей вернулся в дом, поставил пустую кружку на стол и пошёл в комнату жены, хотя и знал, что делать этого ему не надо бы. Не стоило ворошить былое, зачем тревожить больное, и так истерзанное сердце? Но всё равно пошёл, потащился, как на Голгофу. Вошёл и застыл в дверях: здесь тоже ничего не изменилось — ну почему, почему ничего не изменилось?! Это неправильно, так не должно быть! Раскрыл платяной шкаф, и запах — запах его жены, её духов, её тела, — как сладкий яд, проник в него. Схватил первое попавшееся под руку платье, прижал его к лицу, вцепился в ткань зубами и завыл совсем уже по-собачьи, присев возле шкафа на корточки. Безумие накрыло Сергея: вцепилось в кадык, выдавило из глаз слёзы и прибавило решительности — он швырнул платье обратно в шкаф и выскочил из комнаты. В узком коридорчике ногой отбросил в сторону разноцветный коврик, поднял три половицы, под ними обнаружились две бетонные плитки, — вытащил их и по крутой лестнице полез в подпол."},{"kind":"paragraph","text":"Нащупал выключатель, и неяркая лампочка вспыхнула под потолком. Справа от лестницы шли полки, на которых стояли пыльные бутылки с яблочным вином — результат многолетних винодельческих усилий отца Сергея, — банки с вареньем, маринованными огурцами и помидорами; а вот слева в стену был вмурован сейф. Не новомодный, с электронным замком и кучей разных прибамбасов, а старый, ещё советский, несгораемый и весом, наверное, с полтонны. Где его достал дед, как он умудрился притащить сюда это чудовище — один Аллах знал! Вообще-то, по этому подполу видно было, что война, которую дед прошёл от начала и до самого конца, так и не отпустила его. Потому что получился у него не подпол, не подвал, а чуть ли не полноценное бомбоубежище — с бетонными стенами, полом и потолком, с вентиляцией и водопроводом. А в сейфе с незапамятных времён хранился НЗ, собранный дедом. Ключ мягко вошёл в скважину: Сергей три раза провернул его в замке сейфа, опустил вниз здоровенную ручку и потянул на себя дверцу толщиной, наверное, сантиметров десять. Всё было на месте: пятилитровая канистра чистого спирта, пачки соли в полиэтиленовых пакетах, большие коробки спичек (тоже в полиэтилене) и ещё один пакет, за которым Сергей сюда и залез. С пакетом в руке выбрался из подпола, прошёл на веранду, сел за стол и положил пакет перед собой. Последний раз он держал его в руках лет десять назад: из первого пакета вытащил второй, а уже из него достал нечто, завёрнутое в промасленную тряпку. Положил на один из пакетов и аккуратно раскрыл: на тряпке лежал наградной дедовский ТТ с двумя полными обоймами, во всей своей хищной красоте."},{"kind":"paragraph","text":"Дед закончил войну под Берлином и вернулся домой с тремя ранениями, двумя контузиями, орденами Красного Знамени и Славы, кучей медалей и вот этим пистолетом. Сергей помнил, как в детстве бабушка давала ему играться этими медалями, а вот куда все награды делись потом — этого Сергей не знал. Дед умер в девяносто четвёртом году, и пистолет должны были изъять. Но не изъяли, что и неудивительно, если вспомнить тот бардак, что творился в те годы в стране. А сдавать его добровольно никто и не собирался, опять же учитывая всё тот же бардак. И факт остаётся фактом: все медали и ордена деда пропали, а пистолет — вот он, лежал перед ним. Сергей взял пистолет в руку и ощутил его приятную и убийственную тяжесть: снял с предохранителя, передёрнул затвор и, отведя руку в сторону и вниз, нажал на спусковой крючок. Мягко щёлкнул курок — пистолет был хорошо смазан и, несмотря на возраст, работал вполне надёжно. Сергей ещё раз передёрнул затвор и прицелился в зеркало, вставленное в дверку буфета. А мысленно вставил обойму, передёрнул затвор, засунул ствол пистолета себе в рот и нажал на спуск. И всё — боли больше нет! И всё?! Да если бы знать — всё или не всё?! Это конец его мучений или только их начало? Нет ответа…"},{"kind":"paragraph","text":"Какие-то непонятные звуки с соседнего участка вывели его из состояния ступора: то ли кто-то рубил дрова, то ли ломал их через колено. Сергей завернул ТТ в тряпку, засунул в пакет и отнёс его в свою комнату. Посмотрел в окно и выругался вполголоса: на соседнем участке баба Вера пыталась рубить дрова, а годов ей было, если Сергей не ошибался, где-то за девяносто. Что и говорить: удивительные вещи порой творит Создатель с людьми, награждая (или карая?) их долгой жизнью…"},{"kind":"paragraph","text":"Торопливым шагом пересёк лужайку позади его дома, заросшую травой, мимо общего с бабой Верой колодца, вдоль недостроенной беседки — прямо к бабе Вере, неловко орудовавшей топором. Перехватил в воздухе занесённое топорище:"},{"kind":"paragraph","text":"— Здравствуй, баба Вера! Давай-ка помогу!"},{"kind":"paragraph","text":"— Ой! — испугалась старуха. — Хто ето?"},{"kind":"paragraph","text":"Пригляделась подслеповато через смешные круглые очки: одна дужка у очков отсутствовала, и вместо неё была привязана чёрная верёвочка."},{"kind":"paragraph","text":"— Серёжка! Ты, што ли?"},{"kind":"paragraph","text":"— Я, баб Вер, я! — Сергей уже держал в руках её топор. — Давай лучше я дров нарублю…"},{"kind":"paragraph","text":"— А давай! — радостно согласилась баба Вера. — А я тебе потом рюмовку налью!"},{"kind":"paragraph","text":"Сергей внимательно осмотрел топор бабы Веры и решил не рисковать, а сбегал за своим топором. Потом вытащил из сваленных в кучу дров чурбак потолще и установил его на колоду — баба Вера присела на другой чурбак в сторонке и приготовилась поговорить: любила она это дело. Сергей хакнул и с первого же удара развалил чурбак пополам — дело пошло."},{"kind":"paragraph","text":"— А твоя-то где? — с любопытством спросила баба Вера. — На работе, иль поругались, можа?"},{"kind":"paragraph","text":"— Работает… — не стал откровенничать Сергей. Он с наслаждением махал топором: дрова были хорошие, берёзовые и кололись легко, с приятным хрустом."},{"kind":"paragraph","text":"— Ну-ну… — не поверила баба Вера."},{"kind":"paragraph","text":"— Ну а твой где? — просто чтобы поддержать разговор, спросил Сергей."},{"kind":"paragraph","text":"— Которай?"},{"kind":"paragraph","text":"— А у тебя что — много их? — иронично спросил Сергей. И десять, и двадцать, и тридцать лет назад баба Вера называла его просто Серёжкой, а он её бабой Верой. А вот как зовут её мужа, он не знал; даже помнил его плохо — пересекались они с ним нечасто."},{"kind":"paragraph","text":"— Трое было! — гордо ответила старуха. Причём умудрилась это сказать так, что сразу же стало понятно: это только мужей было трое. Подумала недолго и, скорбно поджав губы, добавила: — Всех похоронила."},{"kind":"paragraph","text":"И опять какая-то двусмысленность послышалась в голосе бабы Веры — как продолжение недоговорённой фразы:"},{"kind":"paragraph","text":"— Никто живым не ушёл!"},{"kind":"paragraph","text":"Это было неожиданно. Сергей аж воткнул топор в колоду и с интересом посмотрел на бабу Веру."},{"kind":"paragraph","text":"— Уж я с имя ругалась — страсть! Бывало, дрались даж! Я по молодости-то шустрая была, — вошла во вкус старая и с радостью делилась опытом. — А к вечору — ничё, спать легли и помирились. Потому што спать надо вместе — тады и будет всё миром!"},{"kind":"paragraph","text":"Сергей снова рубил дрова и слушал журчанье бабы Веры о том, как первый её муж пил сильно, отчего и помер, как второго мужа она сама пить отучила и что третий был шибко работящий — вот и надорвался. Сергей чувствовал, как от этого неторопливого рассказа уходит его боль: растворяется в неспешном говорке бабы Веры, в её простых словах и житейской мудрости — без остатка и, что самое удивительное, без водки…"},{"kind":"paragraph","text":"— А можа ты мне ишо и веровку натяниш? — вкрадчиво спросила старуха, когда, на её взгляд, наколотых дров было уже достаточно."},{"kind":"paragraph","text":"— Какую верёвку? — уточнил Сергей, вытирая со лба выступивший пот."},{"kind":"paragraph","text":"— Да бельеву — каку ишо-то? А то вишь: бельишко постираю, а повесить и негде — всё ветром пообдирало."},{"kind":"paragraph","text":"— Инструмент-то у тебя есть — молоток, гвозди — или за своим сходить?"},{"kind":"paragraph","text":"— Всё есть, Серёжка! — опять обрадовалась баба Вера и посеменила в дом. Вынесла кривой молоток, ржавую банку с гнутыми гвоздями, моток верёвки и показала всё это Сергею: — Вот!"},{"kind":"paragraph","text":"Он с сомнением посмотрел на «инструмент» и пошёл к себе на участок за молотком и гвоздями…"},{"kind":"paragraph","text":"Уже под вечер, когда Сергей дров нарубил, воды наносил, верёвку приладил и переделал ещё много чего, что требовалось по хозяйству, они с бабой Верой сидели на крылечке её дома. Он покуривал, с наслаждением ощущая лёгкую усталость в натруженных мышцах, и слушал вполуха очередную life story от бабы Веры. В голове у Сергея было пусто, а на сердце легко и свободно — чёрные вороны над ним уже не вились. Закатное солнце приглушило сочную зелень берёз, росших во дворе, и обмыло стволы сосен красным золотом."},{"kind":"paragraph","text":"— Ничо, Серёжка! — говорила баба Вера. — Жисть она така: сёдни — бела, завтри — чёрна, а ить жить-то всё одно надо!"},{"kind":"paragraph","text":"— Да! — согласился со старухой Сергей. — Наверное, надо."},{"kind":"paragraph","text":"И добавил:"},{"kind":"paragraph","text":"— Спасибо тебе, баб Вер!"},{"kind":"paragraph","text":"— Осспади! — изумилась старуха. — Мне-то за што?"}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
