  published_at = EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-niche-ditya',
  'Ничьё дитя',
  (SELECT id FROM "Authors" WHERE name = 'Андрей Иванов' ORDER BY id LIMIT 1),
  'mrd3/mrd3-niche-ditya.jpg',
  'data:image/jpeg;base64,',
  1586,
  952,
  'Правдивая история из нашей реальности',
  '[{"kind":"image","path":"mrd3/mrd3-niche-ditya.jpg","caption":null},{"kind":"paragraph","text":"Правдивая история из нашей реальности"},{"kind":"paragraph","text":"Меня звали Максим К. В этот год в моём городке Сосна зима оказалась холодной. Хотя, какая зима была в прошлом году, я точно не помнил. Больше всего мне нравилось ждать три вещи: редке просветы солнца в облаках, игры с соседской собакой и когда мама скажет моё имя. Я уже очень радовался, что я Максим. Но самому себя называть было неудобно, и ребята, замечая, когда я шепчу его, начинали цепляться."},{"kind":"paragraph","text":"Я никогда не думал, сколько мне лет, не понимал, зачем это нужно. Соседи говорили, что десять, но развит на семь, что особенный ребёнок. Пусть так и думают. Их всех я не успевал любить, только хорошо думал о них. Кто появлялся редко, о тех вовсе не думал, но, встречая их взглядом, всегда гладил их. Гладил по рукам, а если люди были большие, то обнимал там, где колени."},{"kind":"paragraph","text":"Сегодня не надо было ехать в школу: я долго болел, и в последние два дня меня уже пускали на улицу. Пока я ждал солнца, можно было подумать о маме. «Почему взрослые всегда боятся? Если страх — это такая игра, то она плохая. Хотя я боюсь, например, темноты, но это не страх. Боязнь кончается, когда я засыпаю или уже ночью, когда глаза привыкают к темноте, а у взрослых страх не проходит никогда. Мама, не бойся! Жалко взрослых. Дай им Бог себя!»"},{"kind":"paragraph","text":"У меня была интересная веточка: она разветвлялась на три направления. Я очистил её от коры и всегда носил с собой. Это были мама и мы втроём, я и две старшие сестры. Девочки со мной никогда не играли, но я мог в любой момент достать веточку и представить, что они со мной. Сейчас я смотрел сквозь неё на разрыв в облаках, где должно было показаться солнце. Хорошо бы найти веточку с четырьмя ответвлениями — четвёртая была бы собака. Мы жили в большом городском доме, и родители не разрешали заводить животных. Говорили, что тесно и нет денег. Поэтому я ходил по соседству к бабушке и дедушке в деревянный дом, не к своим, и брал у них из будки собаку. Погулять. Лохматая чёрная дворняжка Альма. Говорят, была старой, наверное, поэтому она не бегала, а медленно ходила со мной. Ласково тыкалась носом и надолго замирала в моих объятиях. Как зовут бабушку и дедушку, я всегда спрашивал, но не запоминал. Может, они обижались."},{"kind":"paragraph","text":"Однажды в школе учительница спросила, у кого есть домашние животные и какие. Не считая кошек и собак, у ребят были попугайчики, черепахи, хомяки и даже ящерицы. У одного меня тогда не было никого. В школе я сдержался, а дома целый день плакал. Потом я нашёл соседскую собаку и бабушку с дедушкой."},{"kind":"paragraph","text":"Меня они видели чаще своих внуков, и я был с ними чаще, чем со своими старшими родителями. Мне это нравилось. Бабушка всегда меня расчёсывала. «Как бесёнок лохматый!» — говорила она. Кто такой бесёнок? Смешная."},{"kind":"paragraph","text":"Скоро Новый год, будет долгий, во всю ночь, салют, мы с собакой будем пугаться. Я буду тихо плакать от радости, есть припрятанные мандарины. Потом принесу очищенный мандарин Альме, но та есть не станет — наверное, потому что старая, а фрукты для детей. Все наши пойдут на улицу, я останусь дома, охранять, так я давно для себя придумал. Альму ведь держат для этого, чтобы стоять на страже. И я с ней. Пусть даже собака лает уже негромко."},{"kind":"paragraph","text":"Всё это я подумал и вспомнил, пока мимо меня проезжала машина. Обычно машины ездят быстро, а эта была медленная. Наверное, её сделали, чтобы не ехать, а больше стоять."},{"kind":"paragraph","text":"Раньше, когда я не ходил в школу, в окру́ге было больше людей и детей. Сейчас нашу и соседнюю школы объединили, вторую школу уже почти разрушили. Я, когда ещё дружил с некоторыми ребятами, тоже ходил бить окна. Окна не сразу поддавались. Но когда получалось разбить, стекло разлеталось, отбрасывая разноцветные отблески. Потом я выбирал интересные осколки, чтобы принести домой в коробку с моими штуками."},{"kind":"paragraph","text":"Некоторым игрушкам у ребят я, конечно, завидовал. Особенно электронным, на телефонах с большим экраном. У меня был телефон на кнопках — я его прятал. В нём были «змейка» и что-то ещё, но я давно решил, что найденные на природе игрушки лучше. Таких ни у кого нет, они только мои. Каждая из них имела своё предназначение. В своём углу — спальня на всех детей была одна и без двери, она давно слетела с петель, а новую не поставили — я расставлял камушки и прокладывал дороги из маленьких стёкол. Мой город никому не мешал, хотя второй папа каждый раз мне говорил, чтобы строительство не препятствовало проходу. Первый папа, который тоже жил с нами, ему было негде, останавливал второго: «Пусть ребёнок играет! И так мало радости»."},{"kind":"paragraph","text":"Взрослые не ссорились, просто не замечали друг друга, нас тоже. Мама обычно сидела на кухне, пила светлый чай. Она никогда не выкидывала пакетик, а клала его снова и снова. Как будто он был ей особенно дорог или вкуснее других. Если бы мама пришла к нам, подсела, спросила о чём-нибудь, я бы построил ещё больше счастья. Как зовут маму, я вспоминал не всегда, но всегда её жалел и старался прикоснуться при любой возможности. Купал меня второй папа. Его руки были сильные, он крутил меня, растирал до красноты — мне становилось тоже хорошо. В конце я его целовал, он отстранялся с улыбкой: «Чего ты, телёнок?»"},{"kind":"paragraph","text":"У ребят в классе почти ни у кого не было папы, а у меня их целых два. Когда иногда приходили полицейские, они меня расспрашивали, не обижают ли они меня. Я отвечал: «Нет». Только иногда в шутку сажают с собой за стол, говорят: «Будешь третьим!»"},{"kind":"paragraph","text":"В большой комнате постоянно работал телевизор, даже если в ней никого не было. За время болезни я услышал несколько новостей, за которые очень переживал. «В Сосне мать выкинула из окна годовалого малыша». Что с ним сталось, я не расслышал. Уверен, он спасся — ведь на улице так много снега, если упасть, то мягко. Я сам прыгал в сугроб много раз. Но трудно вылезать. «Беспризорники разбили витрину в магазине и вынесли три коробки с шоколадками». Вот повезло им. Только я не знал, что значит беспризорники. Наверное, какие-то старшие ребята. Я видел, как такие всегда что-то ищут в заваленном рваными газетами подъезде или на детской площадке. Мне таким крутым никогда не стать. Может, попробую как-нибудь украсть шоколадку или три, себе и сёстрам — только надо про эту идею не забыть."},{"kind":"paragraph","text":"Наш двор был огромный. Учительница говорит, что страна вообще гигантская, а дядя по телевизору сказал, что она даже нигде не заканчивается. Можно ехать на электричке целый год, но не везде есть рельсы, и там, наверное, приходится идти."},{"kind":"paragraph","text":"Сегодня мама запретила забирать собаку, сказала, что можно заразить стариков, надо один день потерпеть. Завтра после школы можно сходить за Альмой. Хорошо. До завтра недолго, за сегодня мама назовёт по имени ещё несколько раз."},{"kind":"paragraph","text":"Болеть мне нравилось: не надо никуда идти и делать бесконечные уроки. И можно есть много лука, который я очень любил. Когда ничего не оставалось, не было еды, я чистил луковицу и съедал её целиком. Было вкусно, но почему-то появлялись слёзы."},{"kind":"paragraph","text":"Иногда объявляли удалённое обучение, но компьютер был один, и тогда учились только сёстры. Для меня мама придумывала повод не подключаться. Её даже вызывали в школу, но она не пошла. Сходил второй папа, который, вернувшись, не стал на меня кричать, а сказал, что ещё один ноутбук купить они не могут. После этого он даже со мной несколько дней занимался. Одна из сестёр сказала, что во многих деревнях ученики идут на холмы, где ловит сигнал, или даже залезают на деревья. Никому не хочется, чтобы на него учителя кричали. Я даже не боялся двоек, но зачем было кричать на меня и на других. Наверное, потому что где-то кричали на них."},{"kind":"paragraph","text":"Ещё сладким воспоминанием были поездки на школьном автобусе. Он собирал много ребят, объезжал тихие дворы. Я всегда представлял, что мы путешествуем, оказываемся в других краях, ждал появления северных оленей или белых медведей. Они, конечно, вот только пробежали за тем домом, но автобуса боятся и не показываются."},{"kind":"paragraph","text":"Над нами жила девочка, она ходила в школу на класс младше. Её родители жили оба в нашем подъезде, но на разных этажах, вообще не общались. И Маша жила то у мамы, то у папы. Часто девочка не хотела идти ни к одному из родителей, и я звал её к себе. Дверь у нас нередко была открыта, и я видел, как она бредёт по лестнице, замирает на площадке. А на прошлый Новый год её отец был уже пьяный и спал, а когда она пришла к маме, та сказала, что уезжает праздновать к друзьям. Маша потом рассказала, что провела всю ночь на площадке, делала вид, что ждёт. Соседи угощали её сладостями, она освободила коробку из-под мусора и складывала еду туда, даже осталось потом надолго."},{"kind":"paragraph","text":"Несколько раз я звал Машу к себе, но ей мои игрушки не понравились, она просто сидела и смотрела на развешенную одежду сестёр. Сегодня она прошла, не снимая курточки, так Маша мне нравилась особенно. Как будто пришла из другой страны."},{"kind":"paragraph","text":"— Хорошо у вас, вон у девочек туфли, а я в кроссовках хожу всю зиму. Мама говорит, что до остановки недалеко, не успеешь замёрзнуть."},{"kind":"paragraph","text":"— Зато кроссовки у тебя красивые, — я правда так думал."},{"kind":"paragraph","text":"— Да, яркие. Но в них набивается снег, и я сижу на уроках с мокрыми ногами. А у тебя полная семья. Не всем так везёт. Я слышала разговор директора с одной учительницей. Он сказал, что пришёл приказ не считать одинокого родителя с ребёнком семьёй, семьи — это только когда все вместе."},{"kind":"paragraph","text":"— Я не думал об этом. Да, когда я вырасту, обязательно так и сделаю, — мне казалось, что в старшем возрасте мальчика выдают девочке, как учебники в школе, и я бы хотел, чтобы меня выдали Маше."},{"kind":"paragraph","text":"Я пока не стал открывать ей свой секрет. Мама иногда давала мне деньги, на пирожок в школе. Но я его не покупал — стоять в очереди мне не нравилось, даже если в ней мало ребят, всё равно они толкаются и обзываются, — а копил монеты на кино. Будет тепло, и тогда накопится и достаточная сумма, и до кинотеатра можно будет пройти не по сугробам. И может, спрошу у сестёр их старые туфли, которые уже стали им малы. Хотя я знаю, что мама отдаёт их ношеные вещи своей подруге, у которой двое малышей. Мне вещи второй папа приносил с работы — они были почти новые. Того мальчика, чьи были курточка и шапочка, я не знал. Думаю, он не стал бы меня обижать. А деньги я хранил в той же коробке, где всё своё. Они были незаметны в куче моего добра. Когда-то папа так назвал мои игрушки: «добро». Мне очень понравилось."},{"kind":"paragraph","text":"— А пойдём на кухню пить чай!"},{"kind":"paragraph","text":"— Ну пошли."},{"kind":"paragraph","text":"Моя мама сидела в дальнем углу стола и смотрела наискосок в окно. Я давно привык к этому и знал, что она не помешает и ничего не скажет."},{"kind":"paragraph","text":"— Здравствуйте, — тщательно выговорила Маша, у меня такое длинное и «задиристое» слово, много «з», не получалось."},{"kind":"paragraph","text":"Маша села боком к столу, может, чтобы не смотреть на маму. Мама, наверное, всё же заметила: прибрала свисавшие волосы назад."},{"kind":"paragraph","text":"Я, как маленький хозяин, нажал на кнопку чайника, подвинул гостье блюдце с оставшимися тремя конфетами. Маша взяла одну и моментально съела. Остальные оставила на чай."},{"kind":"paragraph","text":"Пока вскипал чайник, я не решался поворачиваться — не хотел вспугнуть это приятное время. Маша подошла и встала рядом."},{"kind":"paragraph","text":"— Сколько тебе сахара? — спросил я."},{"kind":"paragraph","text":"— Три кусочка."},{"kind":"paragraph","text":"— Ой, так сладко. Мне хватает одного."},{"kind":"paragraph","text":"— Можно я возьму ещё сахар на потом?"},{"kind":"paragraph","text":"Не дожидаясь ответа, девочка спрятала в карман ещё рафинада."},{"kind":"paragraph","text":"— Больше не надо: мама заругает, — прошептал я, хотя знал, что мама никак не отреагирует."},{"kind":"paragraph","text":"Стульев за столом и на кухне было много. Я первый раз сел туда, где обычно сидел второй папа. Взрослые называли это местом председателя, в узком месте стола."},{"kind":"paragraph","text":"Пили чай молча. Маша не доставала из чашки пакетик и ложку. От долгого заваривания чай у неё стал тёмным. А ложка мешала пить, постоянно скатываясь к руке. Вот смешная. Я свой пакетик сразу положил вместе с другими. Заметил, что многие пакетики переплелись ниточками, их, скорее всего, будет трудно заваривать, понадобится распутывать. В хлебнице остались только два кусочка нарезного батона, их брать было нельзя. Мама учила, что, когда мало остаётся чего-то из еды, вежливо будет спросить у всех, не хотят ли они это съесть. И, только если все откажутся, можно взять самому. Обоих пап не было, они на работе — поэтому я решил, что обойдёмся без хлеба."},{"kind":"paragraph","text":"Чай был горячий, поэтому сидели и пили долго. Я повернулся к плите и чайнику: на кухне был беспорядок, а плита вообще вся жирная, с одинокой сковородкой. Мне стало стыдно перед Машей. Хорошо, что она смотрит в чашку."},{"kind":"paragraph","text":"— Можно ещё? — спросила соседка."},{"kind":"paragraph","text":"— Нет. У нас так нельзя, — ответил я."},{"kind":"paragraph","text":"— Да, спасибо! Вкусный чай. Я пойду."},{"kind":"paragraph","text":"— Хорошо. Хорошо, что пришла, — я прикоснулся к её курточке. Я думал, прикасаться к маме — самое большое удовольствие, а здесь по мне прошла такая волна нежности, которую я испытывал ко всем сразу."},{"kind":"paragraph","text":"Когда Маша ушла, я сел к себе в уголок, спиной к коридору, и так сидел, держа в руках самые яркие стёкла."},{"kind":"paragraph","text":"— Привет! — пришли сёстры из школы."},{"kind":"paragraph","text":"— Да, привет! — ответил я, не поворачиваясь. Вдруг у меня что-то не так с лицом, и они заметят."},{"kind":"paragraph","text":"— Выздоровел? Завтра в школу? — спросила вторая сестра."},{"kind":"paragraph","text":"— Да."},{"kind":"paragraph","text":"— Хочется?"},{"kind":"paragraph","text":"— Не знаю. Утром темно на улице, неприятно."},{"kind":"paragraph","text":"— Попробую тебя проводить, — средняя сестра общалась со мной охотнее старшей, может, потому что была ближе возрастом."},{"kind":"paragraph","text":"— Вот, купили тебе маленькие соки для школы. Смотри, апельсин, яблоко, ананас. На печенье не хватило."},{"kind":"paragraph","text":"— Большое спасибо! — я протянул руку, чтобы посмотреть, такие ли соки."},{"kind":"paragraph","text":"Соки были не такие, малышковые, «Агу-агу!». За такую марку меня дразнили ребята. Однажды я даже не допил сладкий, любимый мной манго. Пришлось выкинуть пакетик в мусорку. Я настолько любил этот сок, что на следующей перемене подошёл и посмотрел в ведёрко — пакетик лежал и не был даже не завален другим мусором. Я было хотел его достать и допить, но обидчики могли следить за ним. От обиды — тогда и сейчас — я беззвучно заплакал."},{"kind":"paragraph","text":"Перед сном я снова вспомнил ощущения от того прикосновения. И старался, чтобы оно сохранилось со мной во сне. Я слышал, что, если сильно захотеть, можно самому себе навести сновидение. Но у меня ни разу не получилось. Как не получалось почти во всём. Но я к этому уже привык."},{"kind":"paragraph","text":"Утром оказалось, что у обеих сестёр не будет первого урока, и проводить меня они не смогут."},{"kind":"paragraph","text":"Все домашние одновременно умывались и толклись на кухне, завтракая, кто чем мог. Второй папа пропустил меня перед собой и защищал спиной ото всех других."},{"kind":"paragraph","text":"— А, не буду сегодня чистить зубы, — сказал в сердцах папа, не надеясь прорваться к раковине."},{"kind":"paragraph","text":"— Да, родственник, иди сегодня без зубов! — второй папа беспрерывно подшучивал над ним. Я запоминал эти шутки и отбивался ими перед сверстниками, помогало."},{"kind":"paragraph","text":"Папа в отместку всем открыл окно настежь. Он никогда ни с кем не ругался, а делал что-то постороннее против."},{"kind":"paragraph","text":"Пасты осталось совсем на дне тюбика, но второй папа смог выдавить дольку себе и мне. Мама ходила по квартире, расчёсывала большой, похожей на ёжика щёткой волосы. Что-то напевала. Я пытался уловить и запомнить мелодию, но за журчанием воды и басом второго папы мелодия пропадала."},{"kind":"paragraph","text":"Я ещё возился с умыванием, а второй папа пошёл проверить мою одежду. Оказалось, не зря."},{"kind":"paragraph","text":"— Мать, ты посмотри, — он поднёс к её лицу мои брюки."},{"kind":"paragraph","text":"Я не знал, что там, но вжался, жаль, в ванной негде было спрятаться. Ругаться в этот раз не стали. Второй папа показал мне, в чём дело."},{"kind":"paragraph","text":"— Вот, по всей штанине размазал сопли. Смотри. Понятно, что сам не заметил."},{"kind":"paragraph","text":"Он долго замывал штанину."},{"kind":"paragraph","text":"— Придётся тебе, брат, с сырой штаниной идти."},{"kind":"paragraph","text":"— Да, спасибо! — сказал я с благодарностью, что не заругал. День начинался хорошо."},{"kind":"paragraph","text":"На столе я допил за кем-то холодный чай. Завтраков у нас не было, это стало привычным — что-то ухватить или просто попить сладкого. Сочок я тоже взял, положил на дно портфеля, под учебники. Выпью потом по дороге из школы."},{"kind":"paragraph","text":"— Максим, телефон у тебя заряженный? — спросила мама."},{"kind":"paragraph","text":"Увидев, что заряда осталось совсем мало, соврал, что да, заряженный. В суете я часто забывал поставить телефон. Он не занимал у меня столько жизни, как у одноклассников, пользовался я им редко."},{"kind":"paragraph","text":"— Ну иди, дорогой, — мама поправила мне шапку и слегка подтолкнула в спину."},{"kind":"paragraph","text":"Я вышел один. У меня был огромный портфель, в который помещалась даже сменная обувь. Мне нравилось таскать такую ношу: я был одновременно как почтальон и космонавт."},{"kind":"paragraph","text":"Сегодня было не очень холодно, поэтому ждать школьный автобус можно было сколько угодно. Подошёл мой одноклассник, мы поздоровались. Мне мама строго наказывала ждать именно школьный автобус и, когда мой товарищ сел в городскую маршрутку, я не стал так делать."},{"kind":"paragraph","text":"В утреннем тумане машины появлялись интересно: фары вдруг загорались сразу рядом с остановкой, висели сами по себе в воздухе, и только потом появлялся автомобиль. Над улицей висел постоянный шум, и звук отдельных машин сливался с жизнью города. Выделялись только грузовики, их фары были выше других, а звук напоминал трубу без мелодии."},{"kind":"paragraph","text":"Автобусы без конца приходили и уходили, люди вращались вокруг остановки. Старшие ребята тоже садились в городские маршрутки и быстро уносились вперёд. Я решил тогда не дожидаться школьного автобуса, боялся, что опоздаю на уроки, нас, не успевших вовремя, построят на первом этаже, наругают и потом дадут тряпки и вёдра, чтобы мы не болтались попусту, как говорил завхоз, а приносили пользу, мыли полы и стены. Трудиться мне нравилось, но я не хотел подводить маму и стыдиться за новое опоздание перед учительницей, которая и так была ко мне очень добра. Тем более я опаздывал сегодня не нарочно, опаздывал не я, а автобус. Это в прошлый раз я специально прыгнул в полынью, чтобы не ходить на контрольную. Пытаясь нагнать товарища, я сел вместе со старшими в обычный транспорт."},{"kind":"paragraph","text":"Дядя водитель что-то у меня спросил, я не расслышал. Я подошёл к нему ближе."},{"kind":"paragraph","text":"— Деньги есть у тебя? Тридцать рублей, — он говорил со мной не поворачивая головы, мне была непонятна его речь. — Где твои родители?"},{"kind":"paragraph","text":"— Давайте я заплачу за пацанёнка, — сказал кто-то из пассажиров, и мне стало за такое неудобно."},{"kind":"paragraph","text":"Я привык ездить не бесплатном школьном транспорте, поэтому не всегда брал с собой деньги. И сегодня я по привычке сложил оставленные мне мамой монеты в свою коробку. Там было уже почти пятьсот рублей. Может, я даже отдам их родителям. Они всё спорят, как отдавать кредит. Хотят взять ещё кредит, чтобы расплатиться с нынешним. Говорят, что все так делают и гори всё огнём. Странное выражение."},{"kind":"paragraph","text":"Чтобы не объяснять дяде эту длинную историю, я вышел на следующей остановке. Куда идти, я примерно знал. Вот берег речки, овраг. Расстояние оказалось больше, чем я ожидал. Перешёл через мост. Хорошо, что туман стал рассеиваться. Я понял, что уже точно опоздал. Увидел магазин, подошёл к витрине, но денег всё равно не было, а заходить, чтобы продавец о чём-то начала спрашивать, я не хотел. Ещё скажет, что прогуливаю, а я не прогуливал. Зашёл, постоял между дверями, погрелся. Но надо было торопиться."},{"kind":"paragraph","text":"Когда я вышел на дорогу, до ближайших домов надо было идти ещё столько же. В этом районе я никогда не был. Даже дойти в соседний двор и потом вернуться я мог не всегда. «Как там сейчас мама? Надо ей позвонить, чтобы не переживала за меня»."},{"kind":"paragraph","text":"Телефон замёрз, и сигнал долго не проходил. Потом несколько минут мама не отвечала на звонок. Телефон сел."},{"kind":"paragraph","text":"Я срезал дорогу, пошёл по сугробам. Вот тропинка. Я уже потом понял, что это были чьи-то звериные следы. Потому что на каждом шаге проваливался, когда по колено, когда больше. А зверёк пробежал совсем поверху, едва задевая порошу. Мне нравились старинные слова. Я их специально заучивал, бывало, приходилось повторять по много-много раз. Я шептал в основном незнакомые слова, но некоторые я специально запомнил. Помимо разных названий снега, мне врезалось в память «веремя» — это по-старинному время. Веремя — от слова «вращение». Я сейчас так же вращался, как это самое время, но найти дорогу не получалось."},{"kind":"paragraph","text":"Тогда я решил идти домой. Я озяб, пальцы рук перестали слушаться, пришлось сжать их в кулаки и греться об себя."},{"kind":"paragraph","text":"Вроде бы показались знакомые дома. Я подошёл, но это был тот же чужой район. Все большие дома в городе были одинаковые. Вдалеке виднелись другие высотки. У нас в городе много рек, и даже взрослые не знали всех названий. Но эту речку, которая протекала между этим районом и нашим, я знал: у неё было забавное название — Канава."},{"kind":"paragraph","text":"Мимо проходили люди, все спешили по своим делам, кто на работу, кто отводил малышей в детский сад. Я никогда не ходил в детский сад, наверное, там хорошо, много ребят, много игрушек. Говорят, можно спать днём."},{"kind":"paragraph","text":"— Мальчик, ты заблудился? — спросила проходившая мимо женщина."},{"kind":"paragraph","text":"Я отстранился и ничего не ответил: мама запрещала разговаривать с чужими взрослыми. Подождав, пока тётя уйдёт, пошёл вдоль реки. Тротуары петляли вокруг домов, и по ним трудно было найти правильную дорогу. Вдоль реки было наверняка хорошо. Да, хорошо, скоро наступит весна, и по Канаве можно будет пускать кораблики. Тем более хорошо, что кораблики никогда не кончались — досочек и веточек из-под снега торчало множество, как будто они сами просились в долгое плавание, где из одной реки можно попасть в другую, а там, совсем далеко, море. Вот бы побывать на море — вырасту, обязательно поеду на море."},{"kind":"paragraph","text":"И тут я провалился в речку. Лёд же должен быть толстый: зима морозная. Но, наверное, я стал весить больше, мама иногда говорила, что вот, растёт маленький кабанчик. Вода обожгла холодом. Провалился только по пояс. Портфель в воду не попал. За мокрые учебники и тетради могли сильно наказать, например, лишить прогулок с Альмой. Выбрался я быстро. Отошёл от реки и побрёл вдоль склона. Я шёл и прятался от людей, чтобы не заметили мои мокрые брюки."},{"kind":"paragraph","text":"«Как сейчас мама? Грустно ей или весело? Когда столько счастья, столько нас, как можно грустить? И скоро Новый год. Пусть мама всегда будет счастлива!» — я думал всё медленнее."},{"kind":"paragraph","text":"Потом я уже не знал, думаю или нет, стал приходить сон, в нём начиналось лето, вода в речке становилась тёплой. В какой-то момент, в котором я уже не чувствовал, но был в нём по-детски счастлив, я, Максим К., умер."}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
