INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-tabor',
  'Табор',
  (SELECT id FROM "Authors" WHERE name = 'Ольга Иванова' ORDER BY id LIMIT 1),
  'mrd3/mrd3-tabor.jpg',
  'data:image/jpeg;base64,',
  1312,
  1186,
  'С невысокого холма по песчаной, залитой жёлтым светом дороге к берёзовому лесочку, к мирно журчащей речке потихоньку шагали разномастные цыганские лошадки, запряжённые в крытые пёстрыми коврами и попонами кибитки. Негром',
  '[{"kind":"image","path":"mrd3/mrd3-tabor.jpg","caption":null},{"kind":"paragraph","text":"С невысокого холма по песчаной, залитой жёлтым светом дороге к берёзовому лесочку, к мирно журчащей речке потихоньку шагали разномастные цыганские лошадки, запряжённые в крытые пёстрыми коврами и попонами кибитки. Негромкий, нежный хор девичьих голосов сливался с пением полевых птах."},{"kind":"paragraph","text":"Старый цыган в рваной, потерявшей цвет рубахе, с большой серебряной серьгой в сморщенном чёрном ухе, погонявший переднего гнедого, поднял руку, крикнул, оглянувшись назад. Повозки свернули к реке."},{"kind":"paragraph","text":"Позвякивая монистами, выбрались из кибиток девушки, легко прыгая по камням босыми ногами, побежали к воде, но строгий окрик бабушки заставил их вернуться."},{"kind":"paragraph","text":"На зелёной лужайке задымился костёр, рядом — гора хвороста. В полукружье повозок, входами друг к другу, стояли несколько рогожных и полотняных палаток. Большой, покрытый ковром шатёр в центре."},{"kind":"paragraph","text":"Женщины хлопотали над закопчённым котлом, покрикивая на полуголых ребятишек, затеявших беготню между палатками."},{"kind":"paragraph","text":"Девушки столпились на берегу, за частыми кустами ивняка, скрываясь от глаз соплеменников, сбрасывали с себя юбки-индараки и, оставшись в одной, нижней, с шумом, с визгом бросались в чистые струи."},{"kind":"paragraph","text":"Накупавшись, принялись за стирку, бережно передавая друг другу серый кусок мыла и старательно раскладывая на тёплых камнях выстиранную одежду."},{"kind":"paragraph","text":"Потом ещё долго отмывали, отстирывали ребятишек, а самых маленьких купали у костра, в нагретой воде, выкопав в земле ямку и выстелив её старой, наполовину стёршейся клеёнкой."},{"kind":"paragraph","text":"Солнце медленно ползло к горизонту. Надвигались сумерки."},{"kind":"paragraph","text":"У костра цыганки кормили детей, деревянными ложками зачёрпывая из железных мисок густое варево. Мужчины, расположившись в стороне, курили, поджидая, когда освободится посуда."},{"kind":"paragraph","text":"Женщины и девушки ели последними."},{"kind":"paragraph","text":"Солнце село за реку, надвинулись синие сумерки. Лёгкий дневной ветерок усилился и будто бы остыл без солнышка."},{"kind":"paragraph","text":"Молодая пышноволосая красавица с тяжёлым, подвязанным чёрным платком животом, неспешно направилась к берегу, вошла по колено в потемневшую воду, не заботясь о намокших юбках. Осторожно склонилась над потемневшими струями, зачёрпывая ладонями, и вдруг насторожилась, услышав странный звук, будто звякнул металл. Выпрямилась, испуганно осматриваясь. Что-то большое и непонятное покачивалось на воде в нескольких шагах от неё. Ужас охватил цыганку. Однажды в детстве ей случилось видеть распухшего утопленника, и братья рассказывали, как неожиданно он всплыл прямо перед ними."},{"kind":"paragraph","text":"Женщина пронзительно закричала. От шатров к берегу бросились трое молодых парней, и следом две длиннокосые девочки лет десяти с одинаковыми лицами. Беременная цыганка, держась одной рукой за живот, другой показывала на неизвестный предмет."},{"kind":"paragraph","text":"Это был большой мешок, в котором что-то тихонько позвякивало. Потянули и решили, что находка зацепилась за корень или острый камень на дне. Но через секунду из воды показался маленький худой человек, вцепившийся руками в верёвку, которой был завязан мешок."},{"kind":"paragraph","text":"— Раклори! Чужая девочка! — закричали глазастые близнецы. Однако старшие быстро распознали свою, племяшку беременной цыганки, девочку Лёльку. Её моментально вытащили на берег, тормоша и расспрашивая, почему она оказалась в воде. Она не отвечала, только оглядывалась, моргая мокрыми ресницами, дрожа, откашливаясь и всхлипывая, крепко сжимала в руках верёвку."},{"kind":"paragraph","text":"— Что у тебя в мешке? — спросила её беременная, и девочка, будто опомнившись, протянула ей верёвку. Любопытные лица склонились над мешком. Парень, первым обнаруживший находку, торопливо пытался развязать намокший узел."},{"kind":"paragraph","text":"— Успеете посмотреть! — раздался грубый окрик старика с серьгой. — Чаялэ! Отведите её к костру, дайте сухую рубашку!"},{"kind":"paragraph","text":"Девушки увлекли Лёльку за собой в рогожную палатку, растёрли холстинкой, заставили переодеться."},{"kind":"paragraph","text":"Тем временем совсем стемнело, и бархатный звёздный шатёр простёрся над табором. Костёр запылал ярче."},{"kind":"paragraph","text":"Цыгане с трудом развязали мешок (старик строго запретил резать хорошую верёвку) и с громкими возгласами доставали из него солдатские кружки, миски, помятую кастрюлю, побитый молочный бидончик без крышки, несколько пустых бутылок с пробками, связку больших и маленьких свечей, смотанных бечёвкой, обёрнутые больничной клеёнкой ношеные сапоги яловой кожи, в одном из которых лежал грубый самодельный нож с деревянной ручкой. В цветастую клеёнку, которой, судя по вытертым сгибам, когда-то накрывали большой стол, были завёрнуты несколько аккуратно сложенных кусков намокшей ткани разных расцветок, местами довольно ветхой, несколько пар шерстяных носков разных размеров, штопанные на локтях детские кофты, две пары детских ботинок с ободранными носами, тщательно смазанных ваксой. Было там ещё немало завёрнутых в тряпки хозяйственных мелочей: слегка ржавые ножницы, жестяная коробка с ухналями (гвоздями для подков), ещё одна с колёсной мазью, костяной гребень, клубок прочных чёрных ниток с иголками в консервной банке и, к визгливому восторгу маленьких цыганок, кукла с торчащими волосами, спелёнатая ситцевым платком."},{"kind":"paragraph","text":"Лёльку привели к костру, усадили на одеяло, налили в кружку чая с сушёными яблоками и хотели было начать допрос, но она, сделав несколько глотков, осторожно поставила кружку на землю, прислонилась спиной к колесу кибитки, закрыла глаза и заснула."},{"kind":"paragraph","text":"— Не троньте её! — сказала бабушка Софья. — Укройте, пусть спит! Завтра день будет!"},{"kind":"paragraph","text":"Когда табор угомонился, девочка проснулась, тихонько выбралась из-под одеяла, приблизилась к затухающему костру."},{"kind":"paragraph","text":"О бабушке Софье цыгане говорили, что она не спит никогда. Действительно, спящей её можно было застать очень редко, и, когда это случалось, чтобы не разбудить, разговаривали вполголоса и шикали на детей. И всё равно она просыпалась через несколько минут."},{"kind":"paragraph","text":"Она сидела на земле у костра, покачиваясь с полуприкрытыми глазами, держа в руке потухшую трубку. Когда Лёлька подбросила дровишек в костёр, перевела на неё взгляд:"},{"kind":"paragraph","text":"— Садись, чайри. Рассказывай."},{"kind":"paragraph","text":"— Что рассказывать, бабушка? Про мешок? Я не знаю… не могу вспомнить…"},{"kind":"paragraph","text":"— Как живёшь, рассказывай. Какие сны видишь…"},{"kind":"paragraph","text":"И девочка стала рассказывать свои странные сны, в которых она жила совсем другой жизнью."},{"kind":"paragraph","text":"А потом до самого утра слушала рассказ старухи о прошлом. О странной судьбе, о первой и единственной любви, о дальней-дальней дороге, приведшей её к этому негаснущему цыганскому костру…"},{"kind":"paragraph","text":"***"},{"kind":"paragraph","text":"Мы никогда не торопились из школы домой. Но с тех пор, как приехала бабушка, почти бежим. Дома всё хорошо, мама больше не плачет, папа приходит вовремя, и в кармане у него обязательно есть что-нибудь для нас: карамельки, пастила или орехи. А ещё дома нас ждёт вкусный обед. Как же бабушка умеет готовить!"},{"kind":"paragraph","text":"Мы врываемся в комнату, где она наводит порядок в шкафу. На кресле лежит ворох моих платьев, Лёшкиных рубашек и старых игрушек."},{"kind":"paragraph","text":"— Пошун ту ман [1], Лёля, — обращается она ко мне, — тут полно того, из чего ты выросла. Ну вот эта кукла, зачем она тебе? Отдала бы детям, у которых нету!"},{"kind":"paragraph","text":"— Конечно, отдам, только кукла эта старая уже, некрасивая. Посмотри, она выгорела, волосы торчат, и губы я ей неудачно накрасила... А что за дети, где они?"},{"kind":"paragraph","text":"— Кукла некрасивая? Для них она красавица! В мой табор отдай."},{"kind":"paragraph","text":"— Бабулечка, не пойму. Ты сама говорила, что твой табор по свету развеялся…"},{"kind":"paragraph","text":"Бабушкин взгляд снова изменился, будто она увидела кого-то, кому была очень рада. Только нельзя было понять, куда она смотрит."},{"kind":"paragraph","text":"— Это здесь он по свету развеялся, табор мой, — говорит она тихо и загадочно, каким-то совсем другим голосом, — а там он живёт… Там я живу, молодая, сильная, там мои сёстры, братья…"},{"kind":"paragraph","text":"Бабушка моя сошла с ума? Или она имеет в виду, что табор живёт в её душе? В воспоминаниях?"},{"kind":"paragraph","text":"Хорошо, что не слышит мама… Я заметила, что в присутствии мамы она никогда не говорит ничего загадочного и странного, никогда не бормочет заклинаний, никогда не вспоминает своих сестёр и братьев, никогда не смотрит в золотую воду, вообще свой медный тазик не достаёт…"},{"kind":"paragraph","text":"Я не успеваю подать стул, и бабушка тихо усаживается на пол. И вот сидит и смотрит непонятно куда, про меня забыла, про уборку забыла, тихонько шевелит губами, то хмурится, то улыбается… Секунды идут… Мне страшно…"},{"kind":"paragraph","text":"Но вот она поворачивает ко мне голову и спрашивает:"},{"kind":"paragraph","text":"— Ну, что сидишь? Кто убирать будет?"},{"kind":"paragraph","text":"Мы сортируем одежду на три кучки: то, что нужно повесить в шкаф, то, что нужно прежде привести в порядок, и то, что нужно выбросить. Таких вещей всего несколько — две тёплые кофточки с вытертыми локтями, две пары стоптанных ботинок, старые Лёшкины штаны непонятно какого цвета. Всё это она особенно внимательно осматривает, складывает старую одежду, потом долго чистит и мажет каким-то жиром ботинки, опускает всё на дно большого мешка, принесённого из кладовки."},{"kind":"paragraph","text":"В этом мешке уже много всякой ерунды, вроде ржавых ножниц, консервной банки или старой бельевой верёвки. Я думала, она это барахло соберёт и выбросит. Только непонятно, зачем консервную банку мыть, выстукивать молоточком заусеницы от консервного ножа, заворачивать в бумагу…"},{"kind":"paragraph","text":"***"},{"kind":"paragraph","text":"Я просыпаюсь безо всякой причины. Будто меня что-то ударило изнутри. Что происходит? Или мне показалось? Я прислушиваюсь к тишине, к ровному лёгкому дыханию брата на соседней кровати, к тиканью часов на стене и убеждаю себя в том, что всё в порядке. Ночь. Все спят. Всё хорошо. Поворачиваюсь на другой бок и пытаюсь заснуть. И слышу звук... Будто тихонько звякнула ложечка о край чашки... Но почему в моём сердце этот звук отдаётся грозным колоколом? Я тихонько поднимаюсь и босиком крадусь на кухню, путаясь в длинной ночной рубашке, ощупывая рукой стену, чтобы не споткнуться в темноте."},{"kind":"paragraph","text":"Дверь плотно закрыта, но увидеть, что там происходит, можно через выпиленный для беспрепятственного проникновения кошки уголок. Сквозь него на пол падает волнующийся тускло-оранжевый свет. Чтобы заглянуть в кухню, нужно лечь на холодный пол."},{"kind":"paragraph","text":"От увиденного дрожь пробегает по телу. Там бабушка, она колдует... Сидит на низкой табуретке, а перед ней её золотая чаша. Седые косы распущены, спина сгорблена, руки со скрюченными коричневыми пальцами в перстнях дрожат над водой… Бабушка шепчет заклинания, надсадно вздыхает и хрипловато стонет."},{"kind":"paragraph","text":"У её ног стоит завязанный верёвкой мешок с тем самым старым барахлом, кажущийся здесь совершенно неуместным…"},{"kind":"paragraph","text":"Я не чувствую ледяного пола — я чувствую ледяной ужас. Цепенею, когда бабушка медленно поворачивает голову и делает мне знак рукой: иди сюда! Источник света — керосиновая лампа за её головой, поэтому лица не различить. Я понимаю, что не могу подняться с пола — тело не слушается, я будто тяжелобольная... Хочу произнести слова извинения, хочу заплакать — не могу, губы будто каменные!"},{"kind":"paragraph","text":"Какая-то сила поднимает меня и ставит на ноги. Деревянными пальцами ощупываю ручку двери, деревянной рукой тяну на себя и на деревянных ногах иду к бабушке. А она будто снова забыла про меня. Руки с костлявыми сморщенными пальцами Бабы-яги застыли над светящейся в полутьме водой, глаза, которые теперь можно рассмотреть, неподвижны и будто бы не живы. Моё сердце колотится всё сильнее, я дрожащим голосом бормочу извинения, но бабушка подаёт мне знак: молчи!"},{"kind":"paragraph","text":"Минуты тянутся бесконечно."},{"kind":"paragraph","text":"Наконец она оборачивается ко мне, и её глаза оживают. Некоторое время молча смотрит на меня, а потом хрипло говорит:"},{"kind":"paragraph","text":"— Лёлушка, сердце моё… пойди, оденься. И приходи ко мне. Что покажу тебе!"},{"kind":"paragraph","text":"Что покажет? Любопытство побеждает страх. Я бегу к себе, надеваю домашнюю кофту и недавно сшитую по-цыгански длинную юбку. Бабушка даёт мне в руку верёвку, которой завязан мешок, сильным движением поверх моих пальцев заставляет сжать руку, шепчет чуть слышно:"},{"kind":"paragraph","text":"— На дар, Лёлушка, подыкх пани [2]… Держи мешок, не роняй!"},{"kind":"paragraph","text":"Я смотрю в заколдованную воду, но не вижу ничего особенного. Обыкновенная прозрачная, чуть дрожащая вода. Вот над ней возникает бабушкина рука. Ладонь опускается на поверхность воды и брызжет мне в лицо. Я вздрагиваю и зажмуриваюсь. Но глаза открываются сами собой, вода оказывается неожиданно приятной. Я вижу всё будто более ясно и чётко. Особенно интересно смотреть в воду."},{"kind":"paragraph","text":"Оказывается, если долго не отрывать взгляда, можно увидеть речные волны. И даже гладкие камешки на дне. И даже корни прибрежных ив, омываемых холодными струями. Очень холодными и прозрачными."},{"kind":"paragraph","text":"Я опускаю в воду руку и ловлю пальцами холод, и резкий, и приятный. Хочется упасть в эту реку, погрузиться с головой... Я чувствую, что вода сейчас поглотит меня и затянет, но клонюсь всё ниже и не могу поднять лицо. Голова кружится, ледяная влага пронизывает, как тысяча стальных ножей. Что это, воронка, водоворот? Я же утону! Но нет, пальцы ног почти сразу касаются дна, а течение оказывается не таким уж сильным. Я выбираюсь на берег по скользкой речной гальке. Ноги у меня босые, но наступать на камни не больно. Холод ушёл, я его уже не чувствую. Мне помогают выбраться на берег, откуда доносятся сквозь шум речной волны громкие и весёлые человеческие голоса."},{"kind":"paragraph","text":"Мой табор стоит на берегу. Я в этом таборе родилась и жила всегда. Здесь все мои родные. Вон ту девочку с бусами красного янтаря на шее зовут Милица, а кучерявого длинноногого мальчишку с подсохшей ссадиной на лбу — Марко."},{"kind":"paragraph","text":"Я бреду босиком по холодной траве. Женщины развешивают на ветках деревьев выстиранную одежду, громко обсуждая свой скудный заработок от гадания, от лечения заговорами деревенских детей. Девушки хлопочут у костра. Мужчины в стороне увлечённо разговаривают, показывают друг другу свои ножи, сравнивая качество ковки. Прислоняюсь спиной к шершавому прохладному стволу старого дерева и закрываю глаза. Опять мне снился сон про совсем другую жизнь. Жизнь, где нет пронизывающего холода и изнуряющей жары, где чисто и светло, где дождь не проникает в тёплое жилище, дети не плачут от голода и не болеют от плохой еды... А всё же я больше люблю эту, настоящую жизнь!"},{"kind":"paragraph","text":"Милица кричит на меня:"},{"kind":"paragraph","text":"— Опять без дела бродишь?! Ну-ка, давай воды принеси! — и суёт мне в руки ведро. — Как вечер, так купаешься! А в ведро воды набрать не уговоришь! Сегодня опять в воду полезешь? И всё по темноте! А ну как не вытащат тебя? Утонешь ведь!"},{"kind":"paragraph","text":"Я торопливо спускаюсь вниз, приподнимая подол индараки, спотыкаясь о корни деревьев, вхожу в воду и ловлю ведром прозрачные струи. Подняться на высокий берег с тяжёлым ведром не так просто, как спуститься вниз, камни осыпаются, цепкие корни путаются в ногах... Милица принимает у меня ведро, спешит к костру и ловко подвешивает его на треногу. Я бестолково суечусь рядом."},{"kind":"paragraph","text":"Мне поручено самое приятное: купать малышей Анисью, Магду и Митю. До чего же я люблю их купать! Дело непростое: Богу помолясь, сначала надо выкопать ямку в земле, ровно такую, чтобы детям было удобно, потом выстелить её соломой и свежими листьями лопуха, а потом клеёнкой, которая в таборе одна и стала уже ветхой, но не дай Господи порвать её — детей не в чем купать будет. Это так делается летом. Когда похолодает, сначала в ямке нужно будет прожечь костёр и оставить стенки тёплыми."},{"kind":"paragraph","text":"Моя сестра Ружана держит на одной руке голенькую Анисью, а второй рукой сжимает пухлую ладошку Митьки. Магда постарше, она стоит рядом в ожидании. Анисья дёргает Ружану за косу и смеётся. Какой же у неё нежный и милый голосок! Ружана и Магда тоже смеются. Я наливаю в клеёнку воду из тяжёлого ведра. Дети радостно плещутся сначала в тёплой, а потом и в остывшей водичке, не мёрзнут. Анисье и Магде нужно ещё прополоскать волосы в настое берёзового листа, чтобы не путались и росли косами, а не «кудлами», как говорит бабушка Софья."},{"kind":"paragraph","text":"Купание заканчивается громким рёвом — дети не хотят покидать остывшую купель. Мы с Ружаной заворачиваем их в шали и поим тёплым молоком из глиняных кружек. А потом любуемся их сладким засыпанием... И наконец относим в палатку, где Марфа кормит грудью ещё одного малыша — беленького приёмыша Алёшеньку. Она его любит едва ли не больше, чем родного сына. Потому что он такой крошечный и болезненный..."},{"kind":"paragraph","text":"Я с трудом открываю глаза. Лицо и волосы у меня мокрые, рубашка тоже влажная. Бабушка крепко обнимает меня и прижимает к своей костлявой груди."},{"kind":"paragraph","text":"— Что со мной было? — спрашиваю я. Голос мой слаб и вял, голова тяжела, язык во рту еле ворочается, руки дрожат, если бы не бабушкины объятия, я бы свалилась."},{"kind":"paragraph","text":"— Я что, сознание потеряла? Почему я мокрая?"},{"kind":"paragraph","text":"— Хорошо всё, ласточка моя! — улыбаясь, напевает мне в ухо бабушка. — Ты сейчас иди к себе, поспи, до утра время есть. Утром поговорим."},{"kind":"paragraph","text":"Она вытирает мне лицо полотенцем, доводит до постели, помогает переодеться в чистую сухую рубашку, укрывает одеялом и ещё долго сидит около меня, гладя мне волосы и тихонько напевая старинную песню о том, что в войне огня и воды вода всегда побеждает…"},{"kind":"paragraph","text":"Брат будит меня, толкая в плечо:"},{"kind":"paragraph","text":"— Лёля! Лёлька! Олька! Вставай, опоздаем!"},{"kind":"paragraph","text":"Обычно я встаю раньше него. Сегодня просыпаюсь с трудом, но в общем чувствую себя вполне свежей и бодрой. Бабушка заплетает мне косы быстро, ловко и аккуратно. Ни один волосок не торчит. Я так не умею."},{"kind":"paragraph","text":"На кухне уже чуть остыла каша в тарелках с янтарным маслом в серединке, тает сахар в чашках с чаем."},{"kind":"paragraph","text":"Бабушка улыбается и гладит нам с Лёшкой макушки."},{"kind":"paragraph","text":"В школе я не могу сосредоточиться на уроках, то и дело возвращаюсь мыслями к своему необыкновенному сну. Целая жизнь приснилась. Не моя, а бабушкина. Будто бы она в той жизни — это я. Вот придём домой, я спрошу у неё, как это может быть, чтобы чужая жизнь приснилась. Откуда я знаю, что сон именно про бабушкину жизнь? А про чью же? Там же был её табор, вся её родня… и всё то, что она любит…"},{"kind":"paragraph","text":"В конце концов я получаю двойку по математике, потому что не могу ответить ни на один вопрос задания. Лёшка поворачивается ко мне, его брови напряжённо изгибаются, он смотрит с недоумением."},{"kind":"paragraph","text":"Вечером я липну к бабушке, и она не отстраняется. Когда мы с ней остаёмся на кухне одни, я, вытирая льняным полотенцем тарелки, говорю:"},{"kind":"paragraph","text":"— Баб, я тебе сон хочу рассказать."},{"kind":"paragraph","text":"— Про табор?"},{"kind":"paragraph","text":"— Откуда ты знаешь?! — теряюсь я. — Да, про табор…"},{"kind":"paragraph","text":"— Знаю я твой сон."},{"kind":"paragraph","text":"— Как?! Тебе он тоже снился?"},{"kind":"paragraph","text":"— Мне разное снилось. Ты снилась, братишка твой снился… Когда ещё я такой, как ты была."},{"kind":"paragraph","text":"— Бабушка, разве так бывает?!"},{"kind":"paragraph","text":"Бабушка складывает в шкафчик посуду и молчит. Я канючу:"},{"kind":"paragraph","text":"— Ба-аб! Ну баб!!"},{"kind":"paragraph","text":"Она забирает у меня из рук тарелку и ставит на полку, а потом поворачивается ко мне и говорит:"},{"kind":"paragraph","text":"— Ну, расскажи, красавица моя, что ты помнишь? Что за сон был?"},{"kind":"paragraph","text":"Я не знаю, с чего начать. Сон был длинный и путаный, я вспоминаю всё новые и новые подробности…"},{"kind":"paragraph","text":"— Ну, кто там был? Милица была? Осип, Марко, Ружана, Аниська? Бабушка Софья была? Про нас с тобой расспрашивала?"},{"kind":"paragraph","text":"Она рассказывает мне мой сон. Я молчу и удивляюсь, только иногда поправляю её: нет, дедушка не болеет… У рыжей кобылы один жеребёнок, это у серой два… Еды хватало… Мука есть, и сухари есть, и ягод много насушили…"},{"kind":"paragraph","text":"Меня вдруг охватывает странное чувство… Холодок в груди… Страх… Почему мне страшно? Я же у себя дома, рядом со мной любимая бабушка, которая не даст меня в обиду никому — ни болезням, ни сердитому завучу, ни папе, ни маме, ни драчуну-брату!"},{"kind":"paragraph","text":"Я беру бабушку за руку, и её сухие пальцы сжимают мою кисть. Я не узнаю своего голоса. Он трепещет и волнуется."},{"kind":"paragraph","text":"— Бабушка, расскажи мне правду! Что это было?! Что за сон?! Это что, на самом деле всё было?! Как?! Как это всё может быть?!"},{"kind":"paragraph","text":"Она некоторое время ещё молчит, а потом говорит устало и нехотя:"},{"kind":"paragraph","text":"— Лёлушка, ты не сердись! Колдовство это. Колдую я… Я уж старая совсем, сил-то нет… Из воды не выберусь… А ты молодая, сильная, ловкая! Такая, как я была. Ты — это я и есть. Тогда. Там."},{"kind":"paragraph","text":"Она снова замолкает, открывает окно и закуривает папиросу. Потом продолжает:"},{"kind":"paragraph","text":"— Знаешь же — табор наш совсем бедный. Нужно помочь было, детонька моя!"},{"kind":"paragraph","text":"Так сильно и громко моё сердце не выстукивало дробь никогда!"},{"kind":"paragraph","text":"— Бабушка, а как же… Не пойму ничего! Там же это так долго всё было! Я там жила, взрослая уже была! А здесь — совсем не выросла!"},{"kind":"paragraph","text":"— Лёлушка, колдовство это… Там жизнь прошла, а здесь — одна секунда времени, малюсенькая-премалюсенькая… Вода это такая в золотой чаше. От колдовства."}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
