  published_at = EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-kolenkina-lyubov',
  'Коленькина любовь',
  (SELECT id FROM "Authors" WHERE name = 'Игорь Галилеев' ORDER BY id LIMIT 1),
  'mrd3/mrd3-kolenkina-lyubov.jpg',
  'data:image/jpeg;base64,',
  890,
  1186,
  '…Ненавижу май! Не пойму — чего в нём может быть хорошего? Чему все радуются-то? Как назло, буквально все вокруг обнимаются и даже целуются. Ненавижу!',
  '[{"kind":"image","path":"mrd3/mrd3-kolenkina-lyubov.jpg","caption":null},{"kind":"paragraph","text":"…Ненавижу май! Не пойму — чего в нём может быть хорошего? Чему все радуются-то? Как назло, буквально все вокруг обнимаются и даже целуются. Ненавижу!"},{"kind":"paragraph","text":"...Потому что меня никто не любит. Сижу один перед окном. Жду. Может, мать придёт — хотя бы так покажет, что родная кровинушка для неё не совсем безразличной стала."},{"kind":"paragraph","text":"Хотя какая там мать? Её же судом родительских прав лишили... Сколько я здесь, в детдоме-то? Считай, полгода уже... За всё время только два раза была. И то для того, чтобы какие-то бумаги справить. Даже яблочко не принесла. Или конфеток. Может, конечно, денег нет, со своим очередным хахалем пропили всё..."},{"kind":"paragraph","text":"Ну вот неужели не тянет на сына одним глазком взглянуть? Мол, как я здесь, не обижает ли кто... Или, может, нужно чего..."},{"kind":"paragraph","text":"Нет, теперь у нас пути разные, разошлись дороженьки. От этого грустно, плакать хочется. Ведь не справится она без меня. Не выживет..."},{"kind":"paragraph","text":"А ещё этот май проклятущий! Будто о новой жизни нашёптывает. Ох, какая же короткая она у несчастного человека — моргнуть не успеешь, глядь, а его и нет уже. Как та черёмуха, которая во дворе нашего детдома растёт, — одна-одинёшенька, грустная, ветерок посильнее дунул, и слетела фата. И снова — не нужна никому до следующей весны, до следующего мая..."},{"kind":"paragraph","text":"Шаги в коридоре за дверью спальной комнаты прервали мои мысли как раз на том месте, с которого обычно я плакать начинал, — так, потихонечку, пока нет никого, чтобы не видел никто — как сейчас: все на занятиях в классе, а я здесь, больным сказался..."},{"kind":"paragraph","text":"Дверь распахнулась, наша заведующая Ольга Лукьяновна, которую среди себя мы Оле-Лукойе зовём, зашла."},{"kind":"paragraph","text":"— Коленька, вот ты где, — говорит. — А я уже обыскалась тебя."},{"kind":"paragraph","text":"Подошла и ладонь к моему лбу прижала."},{"kind":"paragraph","text":"— Всё хорошо? — посмотрела внимательно. — Температура есть?"},{"kind":"paragraph","text":"— Нет у меня ничего, — из-под руки вывернулся. — Чего вы все привязались-то?!"},{"kind":"paragraph","text":"— Коленька, я же волнуюсь, — Оле-Лукойе вздохнула. — Тем более, там приехали к тебе..."},{"kind":"paragraph","text":"Меня как миной подбросило."},{"kind":"paragraph","text":"— Кто? Мамка? — и с подоконника вскочил."},{"kind":"paragraph","text":"Заведующая рукой по моим волосам провела, приглаживая."},{"kind":"paragraph","text":"— Пойдём, мой хороший, сейчас узнаешь."},{"kind":"paragraph","text":"К двери подошла, меня ждёт. Я тапочки нашмыгнул, брюки повыше подтянул, подумал: мол, ремень бы мне, а то падают уже, похудел я что-то совсем."},{"kind":"paragraph","text":"Ольга Лукьяновна меня пропустила и следом вышла, за руку, как маленького, взяла."},{"kind":"paragraph","text":"— Пойдём, а то ведь полчаса уже ждут..."},{"kind":"paragraph","text":"— Да кто там?"},{"kind":"paragraph","text":"— Коленька, я не могу сейчас сказать, кто они для тебя. Или кем они для тебя станут. Но ты не бойся, люди вроде хорошие."},{"kind":"paragraph","text":"— Какие ещё люди?! — закричал я на весь коридор и руку вырвал. — Не нужен мне никто, кроме мамки! Я только её люблю!"},{"kind":"paragraph","text":"Оле-Лукойе остановилась и строго так посмотрела."},{"kind":"paragraph","text":"— Коля, ты уже взрослый, тебе десять лет неделю как исполнилось, — говорит. — Поздравила тебя мама? Нет? Чего молчишь? Вот сам себе и ответь — а ты ей нужен? Она тебя любит?"},{"kind":"paragraph","text":"Помолчала секунду."},{"kind":"paragraph","text":"— Так-то вот, Коленька... А ты говоришь... У тебя, может быть, новая жизнь начинается, счастье наконец-то появится."},{"kind":"paragraph","text":"И, видя, что я насупился, снова за руку взяла."},{"kind":"paragraph","text":"— Пойдём, мой хороший, хотя бы просто познакомишься, поговоришь."},{"kind":"paragraph","text":"Мы уже около двери её кабинета были. Ольга Лукьяновна ещё раз внимательно посмотрела на меня, оценивая, воротник рубашки поправила и постучалась тихонько. Я даже удивился:"},{"kind":"paragraph","text":"— Вы чего к себе стучитесь-то? Вы же здесь, со мной стоите..."},{"kind":"paragraph","text":"Оле-Лукойе улыбнулась:"},{"kind":"paragraph","text":"— И правда... Видишь, как я волнуюсь за тебя..."},{"kind":"paragraph","text":"Дверь открыла и меня легонько в спину подтолкнула — заходи, мол."},{"kind":"paragraph","text":"На фоне солнечного окна я увидел два силуэта — лиц вначале было не разглядеть: майские лучи глаза резали, слезами наполняя. Хотел поздороваться, но из-за комка в горле побоялся слова произнести, чтобы вдруг на девчачий писк не сорваться."},{"kind":"paragraph","text":"В угол кабинета, где большое зеркало висит, отошёл. И тут себя увидел — весь как кулёма какой-то: нескладный, худой, словно из разного конструктора собранный. Вдобавок лохматый — постричься давно пора. И глаза на бледном лице краснющие — наверное, на солнце насмотрелся. Ну не от слёз же..."},{"kind":"paragraph","text":"— Вот, Коленька, знакомься, — Ольга Лукьяновна за свой стол прошла. — Это..."},{"kind":"paragraph","text":"— Не надо, пожалуйста, — прервал её приятный женский голос. — Мы сами..."},{"kind":"paragraph","text":"Я от зеркала отвернулся и на женщину посмотрел. На первый взгляд она показалась вроде бы ничего, доброй, то есть незлобной — лицо красивое, открытое, с осторожной улыбкой — видно, что волнуется. И глаза понравились — с нежностью и теплом смотрят."},{"kind":"paragraph","text":"Женщина встала со стула и рукой на плечо мужчины оперлась. Наверное, муж её. Потому что похожи — я где-то читал, что если в семье всё хорошо, то супруги внешнее сходство приобретают. Учительница литературы говорит, что любовь, как садовые ножницы, — все шероховатости срезает, чтобы в итоге идеальная красота получилась. Поэтому во всём мире влюблённые люди якобы друг на друга похожи и в одно лекало умещаются. По моему же мнению, всё это ерунда. Враньё. Видел я этих влюблённых — ходят, как дурачки, улыбаются непонятно чему, рты раззявив. Мух ловят... Только этим и похожи."},{"kind":"paragraph","text":"Женщина ко мне подошла. Примерно в метре остановилась. Смотрит."},{"kind":"paragraph","text":"— Меня Еленой зовут. А это мой муж (ага, угадал, значит!) Михаил. Как тебя зовут — мы знаем. Мы с тобой познакомиться приехали, Коля..."},{"kind":"paragraph","text":"И руку для пожатия протягивает. Её ладонь оказалась мягкой и тёплой. Приятной... И запах от женщины был ненавязчивый — аромат цветочных духов переплетался с запахами чистоты и свежести. Мамка так никогда не пахла —вокруг неё всегда было облако табачного дыма. А иногда, когда в автопарке, где кондуктором работала, на ночные смены оставалась, — бензином и водкой."},{"kind":"paragraph","text":"— Зачем? — спрашиваю."},{"kind":"paragraph","text":"— Что «зачем»? — не поняла Елена."},{"kind":"paragraph","text":"— Зачем я вам нужен? Что, других детей, что ли, мало? Вон, недавно двоих совсем маленьких привезли — они-то вас за настоящих родителей считать станут. А я что? Я мамку люблю. И неважно, какая она. Другой всё равно не будет!"},{"kind":"paragraph","text":"Последние слова я уже Ольге Лукьяновне сказал. И из кабинета выбежал..."},{"kind":"paragraph","text":"Больше месяца с той встречи прошло. Елена со своим «близнецом» мужем из головы не выходили — сироте доброе слово, что пальто зимой: согревает. Думалось, зря я их обидел — люди-то вроде хорошие. Да и ни при чём они, не виноваты, что у меня жизнь вот так сложилась."},{"kind":"paragraph","text":"Мать так и не приезжала. Закрутилась, наверное, совсем, или забыла вовсе."},{"kind":"paragraph","text":"Предала..."},{"kind":"paragraph","text":"Июнь выдался прохладным и пасмурным, с частыми дождями. Послеобеденный положенный по расписанию сон я не люблю — пустая трата времени. За нами, мальчишками, и не следил особо никто — так, пройдётся воспитатель или сама Оле-Лукойе, посчитает по головам, что не убёг никто, и целый час делай что душе угодно. Кто-то читает, кто-то и правда спит, а я вот в окно смотреть люблю. Сегодня решил посчитать, сколько капелек дождя за три минуты на стекло падает. И всегда ли их количество одинаковое."},{"kind":"paragraph","text":"В четырнадцатом счёте на девяносто шестой капле всё и случилось..."},{"kind":"paragraph","text":"Во двор детдома въехали две машины: одна наша — на этих «Жигулях» завхоз иногда Ольгу Лукьяновну возит, другая — незнакомая белая «Волжанка»."},{"kind":"paragraph","text":"Первой из неё вышла та самая Елена..."},{"kind":"paragraph","text":"Встала около дверцы, на окна смотрит..."},{"kind":"paragraph","text":"Меня увидела, рукой помахала — мол, привет. Поймал себя на том, что улыбаюсь в ответ. Тоже поднял руку и ладонь к стеклу прижал."},{"kind":"paragraph","text":"Подумал, что сердце сейчас из груди выскочит: зачем опять приехали-то? Неужели ко мне? Или, может, кого другого выбрали?"},{"kind":"paragraph","text":"С водительского места «Волги» муж Елены вышел — только сейчас я понял, что он на д’Артаньяна из русского кино про мушкетёров похож. И тоже меня поприветствовал. В это время Оле-Лукойе в здание зашла. Через минуту шаги в коридоре послышались. Всё это время я не дышал. Ждал."},{"kind":"paragraph","text":"Дверь открылась..."},{"kind":"paragraph","text":"— Не спишь, Коленька?"},{"kind":"paragraph","text":"Заведующая подошла и, как обычно делала, волосы на моей голове пригладила. Вздохнула почему-то."},{"kind":"paragraph","text":"— Собирайся, мой хороший, приехали за тобой..."},{"kind":"paragraph","text":"А я и сказать ничего не могу. Вдруг слёзы полились. А как же мамка-то теперь? С собой же взять её не смогу."},{"kind":"paragraph","text":"Ладонью влагу по щекам размазал, и тут Ольга Лукьяновна меня к себе притянула, а сама в мои волосы уткнулась — слышу, тоже плачет..."},{"kind":"paragraph","text":"— Как же ты там будешь, Коленька? — шепчет. — Если вдруг чего — ко мне приходи, я всегда помогу, выручу. Да и так просто пиши, о себе рассказывай..."},{"kind":"paragraph","text":"Отстранилась, из кармашка кофты платок вынула — вначале мне глаза промокнула, потом себе."},{"kind":"paragraph","text":"— Ну всё, мой хороший, пора..."},{"kind":"paragraph","text":"Тумбочки у нас на двух человек были, так что вещей... в один пакет уместить можно: шахматы, которые мне ещё в той, из старой жизни, школе подарили, книжка про подвиг одного лётчика без ног, набор фломастеров, половина из которых уже кончились, и так, кое-что из одежды по мелочи. В общем, всё в одну сумку с ремешком через плечо уместилось."},{"kind":"paragraph","text":"Когда вещи складывал, буквально все в спальной комнате головы от подушек подняли, на меня смотрят — кто тоже со слезами, мол, везёт, семью нашёл, а кто просто так, от тоски по своим родителям или прошлому."},{"kind":"paragraph","text":"Ольга Лукьяновна в дверях стояла, не торопила. Когда я на кровать присел, ко мне снова подошла, рядом устроилась, за плечи обняла, вздохнула."},{"kind":"paragraph","text":"— Посидим, мой хороший, на дорожку..."},{"kind":"paragraph","text":"Пока по коридорам детдома шёл, всё каким-то размытым было, исчезающим. Сразу за дверью во двор меня Елена с супругом встретили. Михаил по плечу тихонько похлопал, мол, держись, и сумку мою взял. На глазах Елены, смотрю, слёзы поблескивают. Но и улыбка была — как бы подбадривала: всё хорошо, переживать не нужно..."},{"kind":"paragraph","text":"Ольга Лукьяновна к ней подошла."},{"kind":"paragraph","text":"— Вы уж берегите Коленьку... — говорит. — Он хороший..."},{"kind":"paragraph","text":"Михаил в это время меня к задней дверце «Волги» подвёл, сначала сумку внутрь положил."},{"kind":"paragraph","text":"— Ну что, братец, запрыгивай. Домой поедем..."},{"kind":"paragraph","text":"Домой..."},{"kind":"paragraph","text":"Через окошко увидел, как две женщины обнялись на прощание — обеим, наверное, поддержка нужна."},{"kind":"paragraph","text":"Елена вперёд села, на меня оглянулась, посмотрела так внимательно, протяжно."},{"kind":"paragraph","text":"Наконец тронулись."},{"kind":"paragraph","text":"Назад смотреть не хотелось — боялся, что не сдержусь. И только когда выехали за территорию, я поднял голову."},{"kind":"paragraph","text":"И вдруг увидел её."},{"kind":"paragraph","text":"Мама..."},{"kind":"paragraph","text":"Она медленно шла от видневшейся невдалеке остановки в сторону детдома. Ко мне шла..."},{"kind":"paragraph","text":"— Мама! Мама!!! — заорал на всю мощь. — Мамочка!!! Ну стойте! Остановите же машину!!!"},{"kind":"paragraph","text":"Михаил нажал на тормоз, и «Волжанка», подавшись вперёд, встала. Открыв дверцу, я выскочил из машины в ещё не успевшую осесть пыль обочины."},{"kind":"paragraph","text":"Мама была в пяти метрах от меня, и это расстояние я преодолел за секунду."},{"kind":"paragraph","text":"— Мамочка! — подбежал, обнял её, в плечо уткнулся. — Ну где же ты была так долго? Ведь чуть не опоздала же! Ещё бы немного, и меня увезли..."},{"kind":"paragraph","text":"А сам плачу, остановиться никак не могу. Мама от меня отстранилась. Молчит. И тут она увидела Елену, которая тоже из машины вышла, — растерянная смотрит на нас."},{"kind":"paragraph","text":"Моя мама к ней подошла. Тихонько так, слышу, говорит:"},{"kind":"paragraph","text":"— Вы, наверное, ему лучшей, чем я, матерью станете, — глаза опустила, в землю смотрит. — С вами он не пропадёт... Привыкнет. А меня забудет. Ведь никчёмная я, родила по случайности. Так что... ваш он теперь..."},{"kind":"paragraph","text":"И дальше пошла, даже на меня не посмотрела."},{"kind":"paragraph","text":"Я было с места сорвался, за ней хотел бежать. Мама мой рёв услышала, как будто только сейчас своего сына увидела."},{"kind":"paragraph","text":"— Уйди от меня! — закричала. — Чего привязался, как пиявка? Вон, у тебя новые родители есть! А меня забудь! Слышишь? Забудь!!!"},{"kind":"paragraph","text":"Что было дальше, я не помню. Наверное, память меня пожалела, стёрла эти самые горькие в моей жизни минуты. Самые горькие слёзы высушила."},{"kind":"paragraph","text":"Да и Елена с Михаилом помогли, поддержали через свою любовь и заботу. От всего сердца за это благодарен им. Но маму я всё равно продолжаю любить. Даже после её смерти — она через год после той истории от рака умерла..."},{"kind":"paragraph","text":"Потом, спустя многие годы, в один из моих приездов в детдом, Ольга Лукьяновна рассказала мне, что мама все те слова специально сказала, чтобы мне легче было."},{"kind":"paragraph","text":"Чтобы забыл её быстрее..."},{"kind":"paragraph","text":"Рассказала, что она больше часа у неё в кабинете сидела, плакала, никак успокоиться не могла. Затем, когда вышла, по той самой дороге, по которой меня увезли, побежала."},{"kind":"paragraph","text":"Догнать хотела..."},{"kind":"paragraph","text":"Но разве догонишь её, жизнь-то?"}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
