INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-drug',
  'Друг',
  (SELECT id FROM "Authors" WHERE name = 'Артём Северский' ORDER BY id LIMIT 1),
  'mrd3/mrd3-drug.jpg',
  'data:image/jpeg;base64,',
  899,
  1186,
  'Мать была в плохом настроении, и Тоня ожидала, когда начнётся. После ужина, во время которого зло гремели тарелки и оглушительно звенели вилки с ложками, девочка пошла в свою комнату — делать уроки. Мать мыла посуду, шум',
  '[{"kind":"image","path":"mrd3/mrd3-drug.jpg","caption":null},{"kind":"paragraph","text":"Мать была в плохом настроении, и Тоня ожидала, когда начнётся. После ужина, во время которого зло гремели тарелки и оглушительно звенели вилки с ложками, девочка пошла в свою комнату — делать уроки. Мать мыла посуду, шум из кухни проникал через приоткрытую дверь. Тоня подошла, чтобы закрыть её, и вздрогнула. Мать стояла у порога, вытирая руки полотенцем."},{"kind":"paragraph","text":"— Куда? Уроки! — яростное лицо, на щеках неровный румянец."},{"kind":"paragraph","text":"Тоня подумала: «Её опять подменили. С работы сюда то и дело возвращается другая женщина, просто она в маминой коже»."},{"kind":"paragraph","text":"В животе у Тони вспыхнул факел."},{"kind":"paragraph","text":"— Я как раз собиралась…"},{"kind":"paragraph","text":"— А ну живо садись."},{"kind":"paragraph","text":"Девочка попятилась к столу, на котором светила лампа и лежали учебники и тетради. Столкнулась со стулом и, быстро повернувшись, села на него."},{"kind":"paragraph","text":"— Ты почему опять так себя ведёшь, а? Почему издеваешься надо мной? — мать вошла в комнату, повесив полотенце на плечо."},{"kind":"paragraph","text":"Тоня раскрыла учебник математики, взяла черновую тетрадку. Мать уселась на кровать поверх покрывала."},{"kind":"paragraph","text":"Начиналась экзекуция."},{"kind":"paragraph","text":"— Я ничего такого не делала, — прогундосила девочка."},{"kind":"paragraph","text":"— Да? А дела по дому почему не выполнила? Я велела пропылесосить. Ты пылесосила?"},{"kind":"paragraph","text":"Материн голос едва не срывался на крик."},{"kind":"paragraph","text":"Тоня сгорбилась на стуле, чуть не уткнувшись в тетрадку носом."},{"kind":"paragraph","text":"— Хочешь меня в могилу свести. Да? Говори. Хочешь? Я из-за тебя седая стану скоро. Старухой стану. Ах, ты хочешь, чтобы я стала старухой! Чего молчишь?"},{"kind":"paragraph","text":"Тоня, потея от страха, помотала головой."},{"kind":"paragraph","text":"— Ну спасибо. Добрая доча позволяет мне оставаться молодой. Земной тебе поклон. Могу спать спокойно. А знаешь, как называются такие девочки, как ты? А? Есть очень взрослое слово для тебе подобных."},{"kind":"paragraph","text":"— Ничего я не делала, — вырвалось у Тони. За этим могли последовать взрыв, удар, крик, но мать осталась на кровати."},{"kind":"paragraph","text":"— Ну и ну-у-у!"},{"kind":"paragraph","text":"Девочка задрожала. Она очень сильно боялась этой фразы и этого тона."},{"kind":"paragraph","text":"— Делай уроки, чего сидишь! Сидит она!"},{"kind":"paragraph","text":"Тоня сделала вид, что решает пример, но перед глазами была пелена, через которую она не различала ни букв, ни цифр. Рука, держащая ручку, взмокла."},{"kind":"paragraph","text":"— Я знаю, что ты говорила вчера с тем мальчишкой из второго подъезда. Думаешь, я дура слепая? Всё я знаю. Ты говорила с ним. И ещё что-то думала про него у себя в головёнке. Что думала? Знаешь, как называют таких, как ты? Мне вот, взрослой женщине, стыдно даже, ей-богу! Зачем ты с ним разговаривала? Я тебе запретила. Из школы сразу домой. Никаких разговоров ни с кем! А может, ты не только с ним говорила? Или не только говорила?"},{"kind":"paragraph","text":"Мать, поднявшись с кровати, подошла к Тоне."},{"kind":"paragraph","text":"— В машины к чужим дядькам садишься? Говори! Садишься? Что они с тобой делают там? Я знаю. Я знаю. Всё по твоим глазам читаю. Тебе нравится, да? Они тебя трогают, целуют в разные места, прости господи. А потом дают конфеты, шоколад, деньги. Ну, где ты деньги прячешь?"},{"kind":"paragraph","text":"Хлёсткий удар влажным полотенцем стал неожиданностью. Девочка вскрикнула, закрывая голову руками. Мать ударила ещё раз, сильнее."},{"kind":"paragraph","text":"— Где ты деньги прячешь?"},{"kind":"paragraph","text":"Тоня лежала ничком на столешнице, мечтая умереть."},{"kind":"paragraph","text":"— Негодяйка! Бессовестная!"},{"kind":"paragraph","text":"Мать схватила её за волосы, несколько раз резко дёрнула, и девочка завизжала."},{"kind":"paragraph","text":"— Таких, как ты, надо сдавать в интернат, чтобы вас там муштровали день и ночь и держали на хлебе и воде. Хочешь в интернат?"},{"kind":"paragraph","text":"Тоня не могла ничего сказать из-за плача. Слёзы стекали по переносице, падали на тетрадь. Нос забился. Но ещё сильнее забилось ужасом всё её тело."},{"kind":"paragraph","text":"— Мама, прости меня."},{"kind":"paragraph","text":"— Простить тебя? Не прощают тех, кто предаёт свою мать. Ясно? Их сдают в интернат навсегда. Думаешь, я буду к тебе приезжать? Привозить передачи? Шиш тебе. А после интерната, когда ты вырастешь, тебя отправят во взрослую тюрьму. Поняла? Тебе там самое место! — теперь она торжествовала, прохаживаясь по комнате и размахивая руками. Картины жизни Тони взаперти ясно представали перед её взором. — И ты и тебе подобные плохие девочки останутся в тюрьме навсегда. Будете работать, чтобы приносить пользу государству. А как ты думала, милая? Задаром тебя никто кормить не обязан, между прочим!"},{"kind":"paragraph","text":"Тоня заикалась, но всё-таки выдавила:"},{"kind":"paragraph","text":"— Я больше так не буду, прости меня, мамочка!"},{"kind":"paragraph","text":"— Чего не будешь?"},{"kind":"paragraph","text":"— Я больше так не буду…"},{"kind":"paragraph","text":"Мать хлестала её, пока не устала рука. Затем передышка — и «серьёзный разговор» продолжился."},{"kind":"paragraph","text":"Тоня получила свободу только через полтора часа и была настолько измождена, что заснула прямо за столом."},{"kind":"paragraph","text":"Вскоре во входную дверь позвонили. Мать, сидевшая в большой комнате перед телевизором, состроила недовольное лицо и пошла открывать."},{"kind":"paragraph","text":"За порогом стоял мужчина с кейсом в руке, одетый в длинный тёмно-серый плащ и шляпу."},{"kind":"paragraph","text":"— Добрый вечер, — сказал он, приветливо улыбаясь. — Прошу прощения, что мешаю вашему отдыху."},{"kind":"paragraph","text":"У мужчины, на вид лет сорока, было приятное гладкое лицо, типичное, но, на взгляд матери Тони, привлекательное."},{"kind":"paragraph","text":"— Да ерунда. Здрасьте."},{"kind":"paragraph","text":"— Я могу войти? Дело в том, что я живу в вашем доме, в последнем подъезде. Я представляю инициативную группу граждан."},{"kind":"paragraph","text":"— Да? — Женщина не помнила, чтобы к ней кто-то обращался, хотя соседей знала неплохо. — И в чём дело?"},{"kind":"paragraph","text":"Мужчина снял шляпу и держал её на уровне груди за тулью. Сейчас он сильно напоминал какого-то киноперсонажа. Этакий чиновник из восьмидесятых."},{"kind":"paragraph","text":"Решив быть милой и вежливой, тем более он казался ей симпатичным, женщина отошла в сторону и прибавила:"},{"kind":"paragraph","text":"— Да вы не стойте там, входите."},{"kind":"paragraph","text":"— Спасибо."},{"kind":"paragraph","text":"Он улыбнулся и шагнул в прихожую. Мать Тони включила бра."},{"kind":"paragraph","text":"— Обувь можете не снимать."},{"kind":"paragraph","text":"Оба одновременно опустили глаза на его туфли. Выглядели они новыми, даже блестели."},{"kind":"paragraph","text":"— Спасибо. Куда пройти?"},{"kind":"paragraph","text":"— А давайте на кухню, — заюлила мать Тони, жалея, что толком не причёсана и в домашнем старом халате выглядит, наверное, как бомжиха. — У меня не прибрано."},{"kind":"paragraph","text":"— Ничего страшного, — заверил её мужчина."},{"kind":"paragraph","text":"В жёлтом свете лампочек выявилась одна странность его лица. Отсутствие бровей и ресниц. Мать Тони, поначалу чуть огорошенная таким открытием, решила, что ладно, всякое в жизни случается."},{"kind":"paragraph","text":"Они прошли на кухню. Мужчина сел на предложенный стул и водрузил кейс себе на колени. Мать Тони хотела сбегать переодеться, но ей была неприятна идея оставить чужого на кухне. Вдруг он что-нибудь украдёт. Мужчинам она не очень доверяла, хотя конкретно этому могла бы простить небольшую диверсию на своей территории."},{"kind":"paragraph","text":"Короче, решила остаться."},{"kind":"paragraph","text":"— А в какой вы квартире живёте? — спросила мать Тони, садясь напротив."},{"kind":"paragraph","text":"Мужчина положил шляпу на стол и ответил:"},{"kind":"paragraph","text":"— Мне больше негде жить. Я бы хотел остановиться у вас. Метры позволяют. Думаю, и наш общий бюджет станет вполне подходящим для безбедного существования."},{"kind":"paragraph","text":"Мать Тони подалась вперёд."},{"kind":"paragraph","text":"— Что?"},{"kind":"paragraph","text":"— Вопрос ремонта внутридомовой электросети будет решаться на общем собрании через неделю, а сейчас я хотел бы взять вашу подпись. Что вы соглашаетесь на ремонт электрощитов. Сами видите, в каком они у нас состоянии, — мужчина открыл кейс, сунул в него руку, вытащил листок бумаги и положил на стол. Рядом пристроил ручку. Мать Тони бросила взгляд на бумагу: в два столбика на ней стояли подписи жильцов дома."},{"kind":"paragraph","text":"— Извините, я вас не поняла. Что вы сказали до этого?"},{"kind":"paragraph","text":"— До чего?"},{"kind":"paragraph","text":"— До… того, как достали список."},{"kind":"paragraph","text":"— Я вас не понял. Вот, смотрите, здесь вам нужно только поставить свою подпись."},{"kind":"paragraph","text":"— Я поняла. Но что вы говорили раньше? — напирала мать Тони. — Что вам негде жить и вы собираетесь переехать ко мне."},{"kind":"paragraph","text":"— Нелепая мысль, — махнул рукой мужчина."},{"kind":"paragraph","text":"У матери Тони заколотилось в висках."},{"kind":"paragraph","text":"— Ничего не пойму."},{"kind":"paragraph","text":"— Это вам не будет стоить ни копейки, я же много зарабатываю. Знаете, кем я работаю? Главным получателем денег в нашей стране."},{"kind":"paragraph","text":"Женщина вытаращила глаза."},{"kind":"paragraph","text":"— Что?"},{"kind":"paragraph","text":"— А как же! Мы не просто кто-то так, а очень даже величина."},{"kind":"paragraph","text":"— Да что вы несёте? — взорвалась мать Тони. — Вы чокнутый? А ну, убирайтесь отсюда!"},{"kind":"paragraph","text":"Он улыбался и глядел на неё, не мигая."},{"kind":"paragraph","text":"— Мы будем заниматься сексом всего один раз в неделю. Ничего страшного, да?"},{"kind":"paragraph","text":"— Чего-о?"},{"kind":"paragraph","text":"Её вопль нисколько не напугал и не смутил его."},{"kind":"paragraph","text":"— Только раз в неделю. Больно не будет. У меня есть все документы, — продолжал гнуть своё мужчина."},{"kind":"paragraph","text":"— Что?"},{"kind":"paragraph","text":"Его бы ударить изо всей силы, вцепиться в волосы, но мать Тони чувствовала, как её воля тает и слабость расходится по телу."},{"kind":"paragraph","text":"— Да не волнуйтесь вы так, — из кейса появилась папка, которую гость положил на стол и открыл. Мать Тони бессильно наблюдала. — Вот, тут сказано, когда и при каких обстоятельствах вы попали в интернат, а тут — что вас перевели в тюрьму, когда вам исполнилось восемнадцать лет. Убедитесь, все печати и подписи на месте. Ваш номер: 135609."},{"kind":"paragraph","text":"У матери Тони закружилась голова. Мужчина цокнул языком."},{"kind":"paragraph","text":"— Взаимопомощь граждан очень важна, — заметил он. — А это справка о ваших дисциплинарных взысканиях. Все грешки, так сказать."},{"kind":"paragraph","text":"Она поглядела на документ, но не смогла различить ни одной буквы."},{"kind":"paragraph","text":"— Жить мы будем душа в душу. Вся моя зарплата будет ваша до копейки. Электрощиты в доме починим."},{"kind":"paragraph","text":"— Как вас зовут? — прошептала мать Тони."},{"kind":"paragraph","text":"— Никак. Имена отменили ещё месяц назад, вы что, не помните?"},{"kind":"paragraph","text":"— Нет, — она не помнила. — Я тогда просто поговорила с тем мальчиком. И всё."},{"kind":"paragraph","text":"— Ай-ай, а ведь хорошие девочки так не делают. Ни при каких обстоятельствах, — мужчина уставился на неё. Улыбка приклеилась к его гладкому лицу и не сходила. — И за свои преступления попадают… — он хлопнул по папке ладонью. — Но… вы сбежали. До сих пор неизвестно, каким образом вам это удалось. Вы не могли бы прояснить?"},{"kind":"paragraph","text":"Мать Тони молчала, глядя в пол."},{"kind":"paragraph","text":"— Жестокость, конечно, это нехорошо. Но ваше упрямство толкнёт меня на крайние меры, понимаете? Я знаю один способ наказания. Кладёшь в носок брусок мыла и бьёшь, как плетью. Очень больно, и никаких синяков при этом — чудно, не правда ли? Я испробовал этот способ множество раз. Я представляю инициативную группу граждан. Я живу в последнем подъезде."},{"kind":"paragraph","text":"— Прекратите! — опираясь на спинку стула, мать Тони с трудом встала. — Убирайтесь, пока я не вызвала полицию!"},{"kind":"paragraph","text":"— Зарплату буду отдавать всю до копейки, — отозвался мужчина, показывая ей папку."},{"kind":"paragraph","text":"От удара папка полетела на пол, теряя лежащие в ней бумаги."},{"kind":"paragraph","text":"— Плохих девочек, ставших плохими женщинами, которые сбежали из тюрьмы, полиция арестовывает особенно охотно."},{"kind":"paragraph","text":"Мать Тони посмотрела на стол рядом с мойкой — там лежал кухонный нож. В её мозгу нарисовалась картина: взять нож и воткнуть сумасшедшему в голову. И бежать. Стоп, а как же Тоня?"},{"kind":"paragraph","text":"Девочка вошла на кухню, заспанная и вялая, однако при виде мужчины оживилась."},{"kind":"paragraph","text":"— Ты! Пришёл!"},{"kind":"paragraph","text":"— Я пришёл, — улыбаясь, ответил он."},{"kind":"paragraph","text":"— Я думала… думала, что этого никогда не случится… я так ждала!"},{"kind":"paragraph","text":"Мать Тони попятилась от них обоих и упёрлась в стену. Дальше идти было некуда."},{"kind":"paragraph","text":"— Я пришёл, — механически повторил гость. Он встал, резво собрал бумаги с пола и вернул их в кейс. — Одевайся, Тоня, мы уходим."},{"kind":"paragraph","text":"— Сейчас! — игнорируя мать, обрадованная девочка помчалась в свою комнату."},{"kind":"paragraph","text":"Женщина открыла рот, но тут же закрыла."},{"kind":"paragraph","text":"Мужчина надел шляпу и взглянул на неё. В его взгляде было то, чего мать Тони не видела уже много лет. Может, и всю жизнь. Сочувствие."},{"kind":"paragraph","text":"Так они стояли друг напротив друга, пока, одетая к выходу, с рюкзаком в руке, не вернулась Тоня."},{"kind":"paragraph","text":"— Я готова, — заявила она."},{"kind":"paragraph","text":"— Хорошо, милая."},{"kind":"paragraph","text":"Они пошли в прихожую. Там мужчина проверил, как хорошо сидит на Тоне защитный комбинезон, не нарушена ли герметичность. Помог надеть противогаз. Девочка засмеялась, но звук вышел глухой."},{"kind":"paragraph","text":"Выглянув в коридор, женщина только сейчас поняла, что забыла спросить у гостя, почему он сам без защитного костюма."},{"kind":"paragraph","text":"— Доброго вечера."},{"kind":"paragraph","text":"— Прощай, мама, — помахала на прощание Тоня, и вместе с мужчиной шагнула за дверь."},{"kind":"paragraph","text":"Спустились они на первый этаж, вошли в переходную камеру, дождались открытия внешнего люка и очутились во дворе."},{"kind":"paragraph","text":"Мужчина взял руку Тони, одетую в перчатку, и они зашагали к выходу из арки."},{"kind":"paragraph","text":"Бóльшая часть квартала была руинами, над которыми клубился зеленоватый токсичный туман. Небо сплошь заполнял оранжевый свет."},{"kind":"paragraph","text":"На следующий день, разбирая вещи дочери, женщина нашла в её альбоме для рисования изображение мужчины в плаще и шляпе. Он улыбался и держал в руке кейс. Под рисунком стояла подпись неровными печатными буквами: ДРУГ."}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
