INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-avtobiografiya-borhesa-napisannaya-ne-im',
  'Автобиография Борхеса, написанная не им',
  (SELECT id FROM "Authors" WHERE name = 'Оганес Мартиросян' ORDER BY id LIMIT 1),
  'mrd3/mrd3-avtobiografiya-borhesa-napisannaya-ne-im.jpg',
  'data:image/jpeg;base64,',
  1586,
  1023,
  '«Мать звала меня Хорхе, как надо. Я гулял допоздна, рвал кузнечикам крылья и приделывал к ним страницы моих будущих произведений. Я зажигал гусеницу и курил её, превращая в бабочку моих лёгких её. Дрался с пацанами, буду',
  '[{"kind":"image","path":"mrd3/mrd3-avtobiografiya-borhesa-napisannaya-ne-im.jpg","caption":null},{"kind":"paragraph","text":"«Мать звала меня Хорхе, как надо. Я гулял допоздна, рвал кузнечикам крылья и приделывал к ним страницы моих будущих произведений. Я зажигал гусеницу и курил её, превращая в бабочку моих лёгких её. Дрался с пацанами, будучи слепым на старости лет: я экстраполировал неведение будущего к себе. Приходил Хем и издевался надо мной: выкручивал руки и насиловал мозг — объяснял свою схожесть с Довлатовым. Я пил водку с тринадцати лет, затыкая бутылки пальцами и так ходя. В школе меня сравнивали с Рембо. Я так и учился: тридцать учеников, двадцать девять из которых — Верлен»."},{"kind":"paragraph","text":"«Я врубался в математику с ходу, в геометрию тоже: их я перенёс в литературу, став великим математиком и геометром. Девочки меня любили: пинали мой портфель, звали Гуинпленом и Гобсеком, мочились в моё пиво, когда я его забывал на подоконнике в коридоре, переезжали мои тетради на велосипедах. Член мой набухал при виде девчат и представлял собой микрофон, в который они пели песни о любви»."},{"kind":"paragraph","text":"«Я рос непослушным мальчиком, снимал цилиндр при виде треугольника у девочки между ног, мама целовала меня в мой лоб, за которым хлопали двери и выли голоса. В голове моей Бирс насиловал всех встречных женщин и мужчин и писал свой знаменитый словарь, наполненный трупами всех великих имён. Однажды я поцеловал учительницу в пятую точку: она наклонилась над партой соседа, и я припал к её полушарию. Она вызвала в школу мою мать и сказала: \"Он не мог задрать моё платье?\" Мама расплакалась и обещала взяться за меня всерьёз. Она купила мне велотренажёр и заставила выпускать в комнате пар, чтобы она пропиталась мной, а я стал кроватью, шкафом и столом»."},{"kind":"paragraph","text":"«По ночам я курил на балконе и смотрел на звёзды, выдавливал их, как прыщи, и глотал жёлтый гной света и тепла, пока не накрывала полная тьма, настоящее затмение, и я онанировал на открытки с голыми женщинами, передавая им свою силу и страсть. Моё сердце билось быстрей: это оно кончало кровью в каждую клетку тела, распластанного вертикально везде и вбирающего в себя книги \"Война и мир\" и \"Игрок\". Так проходили дни, напичканные динамитом по имени Ницше, снёсшим статую Христа и вставшим вместо него, но живым, как он сейчас и стоит в каждой Земле на Земле»."},{"kind":"paragraph","text":"«Забегая во взрослую жизнь, скажу: я стал телом — полностью мозгом: личинкой жука, одевшейся позже в него, то есть в гроб. А пубертатом я порой не хотел ничего, чаще всего всегда: ни есть, ни пить, ни мастурбировать, ни женщин, ни мужчин, ни сигарет, ни наркоты, ни книг. Впрочем, их я хотел, читать как писать и писать как читать. А для этого нужны сигареты или водка \"Хемингуэй\". Это не странно. Естественно и для всех. Сигарета — лодка, плывущая по морю Хайнекен или Бад, пока оно тихо и не шумит»."},{"kind":"paragraph","text":"«Встречался с девчонкой Викторией, находил её смешной, дразнил её, задирал ей платье и представлялся Лавкрафтом, пишущим её членом, макаемым в её вагинальную кровь. Гуляли по машинам, наступали только на них, припаркованных по краям, и я ей говорил: это смерть. Жизнь — ходьба по едущим между ними авто. Вика смеялась и задирала платье, показывая трусы с фрагментами картин Ван Гога, и спрашивала, не хочу ли я их дорисовать своей кистью. Я молчал и целовал её руку, которую держал, чтобы она не взлетела и не зажала солнце в кулак»."},{"kind":"paragraph","text":"«Однажды с друзьями мы забрели на свалку, где стоял разбитый автобус с проломленной черепной коробкой, которая — коробка передач. Мы расселись на драные сиденья, закрыли глаза и поехали — от планеты к планете, потому что негодное здесь работоспособно и нужно там. Маркос рулил, мы ехали, Джимми и Эрнесто высунули ноги в окно, и мы смотрели на звёзды, торчащие вместо фар, светофоров и фонарей. Переносились от луны к луне и колёсами вспахивали поля, сажая на них высыпающиеся подшипники — семена»."},{"kind":"paragraph","text":"«Вскоре начались опыты письма, литературы, я писал Вике письма, стараясь выразить в объёме себя, чтобы бумага с текстом воспринималась как самолётик или кораблик, даже так: как они оба сразу, что есть высшая ступень гениальности, зовущая меня к себе»."},{"kind":"paragraph","text":"«Я много читал, пока не понял, что перестал отличать золото от дерьма: крайности сходились в моей голове и шире. Описывали круг, пока я не распрямил его, сделав из колеса крыло. Сменил таблетку на косячок. Сигарету саму»."},{"kind":"paragraph","text":"«Солнце всходило в моём уме в виде кукурузы, представляло собою стебель и початки, торчащие по сторонам, распускающиеся жёлтыми лучами — зёрнами, брызжущими свой сок в кастрюле и зовущие их съесть, чтобы заменить зубы своими телами и начать тоже светить, сделать каждую голову звездой, антонимом желудку — чёрной дыре»."},{"kind":"paragraph","text":"«Тогда я открыл для себя Акутагаву, стал внедряться в него и понял: читать — дописывать или переделывать книгу в новом формате, скажем, левого полушария, заносить в себя буквы и после сеять их, разговаривая, когда они вылетают из уст, падают в землю или в асфальт и дают ростки в виде пшеницы, ржи и домов»."},{"kind":"paragraph","text":"«С Викой первый секс состоялся в ржавом рефрижераторе, когда мы разделись и стали читать переписку Вольтера и Екатерины Второй, жёсткие слова входили в наши уши и размножались с нашими мозгами, интеллектами, направленными друг к другу, целовались так: поставили две книги рядом, прижали их и уронили на пыльный пол, как в реку или озеро, понимая, что вода — это пыль, если шире — то прах, состоящий из бывших \"мама, я хочу есть\", \"вам за урок пятёрка\", \"я хочу куннилингус\", \"вы арестованы\", \"сердце моё — люблю\". Ушли после соития, оставив наши тела — книги — тем, кто захочет заняться любовью с помощью них»."},{"kind":"paragraph","text":"«Я поступил в университет, расстался с Викой, погрузился в мир алкоголя, зачётов, экзаменов и веселья, стал гулять толпой, щемить малолеток, иногда баловаться травкой, жить наобум, наугад, но понимать: каждая случайность — закономерность, непонятая пока. Увлекался боксом, поднятием тяжестей, прокачкой двуглавых и трёхглавых мышц, влюблялся в девчонок, относясь к ним как к спичкам, а не зажигалкам: поджигал ими свой член и курил его, выкидывая бычок»."},{"kind":"paragraph","text":"«Другом стал Хулио, вместе ходили, драли шлюх в борделях, читали Ницше, словно гуляющего с нами третьим, как будто \"мясом\", сбежавшим с нами из тюрьмы, которая — свобода, торт, то, что не купили ещё, а если человек продаётся, его нарезают на куски — камеры, квартиры в честь праздника, потому день рождения или Новый год — темница, воля — обычный день, когда утро неотличимо от вечера»."},{"kind":"paragraph","text":"«Кортасар больше меня писал, курил меньше, но пил, создавал умопомрачения в тексте, а я уплотнял его, сжимал, был электричкой и трамваем в час пик, представлял собою путь, утро и вечер, он, наоборот, провоцировал день и ночь — таким образом, я — весна и осень, он — лето и зима»."},{"kind":"paragraph","text":"«Встретил, возвращаясь домой пьяным с занятий, Викторию, она бросилась мне на шею и заплакала, разрыдалась, подарила мне шоколадку и дальше потекла из глаз «Мерседесами», скатывающимися по ней, попадающими на асфальт и летящими по дорогам, сигналя и махая флагами Аргентины. Я не утешал её, давал выплакаться вволю, гладил ей спину, плечи и целовал ей лицо. Когда печёная картошка утихла и улыбнулась мне трещиной рта, я повёл её в кафе \"Насьональ\" и угостил жареной рыбой и соком. Мы посидели час и разошлись, решив встречаться порой. Она работала продавщицей цветов, торговала любовью природного мира, переходящего в человеческий, но вянущего быстро. Именно поэтому она любила стихи как искусственные розы и астры, вечные на земле, и мечтала о магазине книг, чтобы стать человеком и богом»."},{"kind":"paragraph","text":"«Первые рассказы напечатали, получил гонорар, собрал друзей за столом, зачитал пару строк, произнёс тост, выпил, как и все, осушил взглядом текущий из люстры свет, оставил всех во тьме, зажёг свечки и в интимной обстановке продолжил празднество, пиршество наших душ, двигающихся на танцполе, сосущихся в туалете, пока мы отдыхаем здесь»."},{"kind":"paragraph","text":"«С Хулио шатались на улице, держали телеграфный столб, чтоб он не упал и не устремил за собой целый мир, его проституток, сутенёров, жён, дочерей, мужей и самые умные стихи Маяковского, долетающие досюда и диктующие очень сильное бытие мужчин. Мы смеялись и пели, гоготали над прохожими, тыкали пальцами в них и хлопали в ладоши, когда падали и валялись на земле. Целые вселенные вращались в наших умах, распевая незатейливые песни матросов. Увлекли даже Лондона, тень его, копию или его самого, увидев вдали и подозвав к себе. Взяли у него сигарет, покурили с ним и похвастались тем, что он известнее нас. На это он улыбнулся, поднял шляпу, показал золотой зуб и прыгнул в фиакр, укатив от нас прочь»."},{"kind":"paragraph","text":"«Дома я сел за стол и начал писать: \"Кино — когда ты неподвижен, а оно нет, литература — наоборот. Это спор Гераклита и Парменида. Второй убирает время, убивает его. Он — Георгий Победоносец, пронзающий змея копьём. Что касается фильма, то он умирает или кончает с собой, в честь чего в конце идут титры как некролог, потому что ‘Птицы’ и ‘Зеркало’ — ты мёртв, они — нет, а ‘Улисс’ и ‘Старик и море’ — трупы они, ты живой: чем больше пишется, тем меньше смерти и всеобъятней жизнь\". Принял холодный душ, отрезвел, но не полностью, позвонил Вике и сказал, что её люблю»."},{"kind":"paragraph","text":"«После вуза писал кандидатскую в аспирантуре, вёл занятия, обучал студентов тому, как не быть собой, иметь десять тел и кочевать по ним, распределяться, делиться, светить фонарём изнутри, в пальцах, предплечьях, локтях, плечах и так далее, отдыхал на заседаниях кафедры, курил на улице, общался с девчонками, один раз даже разнял дерущихся парней, наехавших на него как на равного себе, на что он показал удостоверение и пригрозил отчислением»."},{"kind":"paragraph","text":"«Признание долго шло, не особо публиковали, видели во мне Непонятного, предлагали писать подлинней, ясней и проще, я ругался с редакторами, спорил, доказывал неизбежность тьмы в тексте, так как при свете не видно звёзд, но на это смеялись надо мной и возвращали перечёркнутой рукопись, запрещённой крестом»."},{"kind":"paragraph","text":"«Когда смотрел телевизор, услышал о смерти Кокто, но не поверил тому, решил, что кругом глобальный обман: никто и ничто не умирает, ещё ни одно живое существо не скончалось, хоронят чучела и муляжи, не людей, что же касается трупов на улице — их специально изготавливают и бросают, опрыскивая духами с запахом разложения и гнили, скрывая тем самым улёт на другие планеты их всех: вот и всё, смерти нет»."},{"kind":"paragraph","text":"«Я женился на Вике, переехал с ней в маленькую квартиру, писал по ночам рассказы и кандидатскую, днём работал всё там же, читал курсы о Достоевском и Рембо, не завидовал никому, хоть у Хулио уже вышла книга, получила похвалу, разошлась большим тиражом, лопнула на корешке у некоего Диего, о чём он рассказал в газете, похвастался этим, отметил это как переполненность мыслями автора издания и произнёс \"адьос\"»."},{"kind":"paragraph","text":"«Дети наши выбегали из нас по ночам, хватали конфеты из холодильника и исчезали на улицах, растя на них поварами, пекарями, курильщиками опиума, водителями и философами Земли, чтобы она была внутри текста, отсутствуя вне его»."},{"kind":"paragraph","text":"«Устроился в библиотеку через несколько лет, стал считать все книги своими, боролся в этим, не выдержал, проиграл, читал первые рассказы Павезе, уносился с ним прочь, заходил домой, целовал жену, обсуждал политику и любовь как одно, сворачивал лаваш в трубочку, начинённую сыром и перцем, и ел, так как не хотел, пролистывал газету и ложился в носках на диван, желая как-нибудь встретить своего двойника и обменяться книгами \"Идиот\" и \"Игрок\", пойдя себе дальше — в края, где их нет»."},{"kind":"paragraph","text":"«Возраст струился во мне, набегал, исчезал, наваливался с годами других людей и вообще на меня, старил, лишал сил, награждал болезнями и подарил как-то мысль, что рыба в первую очередь есть уха и консервы, а потом уже она сама»."},{"kind":"paragraph","text":"«Получил премию за сборник рассказов, дали немного денег, попросили сказать что-нибудь, что я и сделал, молвив: \"Писать — это зачёркивать, уничтожать написанное до тебя: писатель тот, кто делает пустотой и отсутствием ‘Бедную Лизу’ и ‘Великого Гэтсби’. Кто больше сотрёт, тот и гений\". Я ушёл, добрался домой и разложил себя по годам, месяцам и дням, разделился и стал не человеком, но понедельником, вторником и средой»."},{"kind":"paragraph","text":"«Умер, стал трупом, перестал дышать, двигаться, писать, целовать жену, поступил в гроб, ушёл под землю, через день выбрался на волю при помощи спрятанной сапёрной лопатки, которой разгоняли митинг в Грузии, вернулся к себе, заварил кофе, встал с ним на балконе и начал курить, делая маленькие глотки»."}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
