INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-basseyn',
  'Бассейн',
  (SELECT id FROM "Authors" WHERE name = 'Алексей Колесников' ORDER BY id LIMIT 1),
  'mrd3/mrd3-basseyn.jpg',
  'data:image/jpeg;base64,',
  1586,
  892,
  'Дешёвое хуже одновременно и дорогого, и бесплатного. Я покупаю билет в бассейн на одиннадцать ночи потому, что он самый дешёвый; в это время любители спорта давно уже спят. Я выбираю шкафчик, раздеваюсь и ухожу в душевую',
  '[{"kind":"image","path":"mrd3/mrd3-basseyn.jpg","caption":null},{"kind":"paragraph","text":"Дешёвое хуже одновременно и дорогого, и бесплатного. Я покупаю билет в бассейн на одиннадцать ночи потому, что он самый дешёвый; в это время любители спорта давно уже спят. Я выбираю шкафчик, раздеваюсь и ухожу в душевую. Под слишком горячей водой растираюсь мочалкой, вскрикивая от ожогов, потом натягиваю на мокрую задницу плавки, обтираюсь, чтобы не страдать от холода по пути к бассейну. Выхожу к воде. Одиночное плаванье одинокого человека."},{"kind":"paragraph","text":"Необходимость плавать ближайшие сорок минут меня угнетает; я прислушиваюсь к организму и ощущаю то боль, то усталость. Не хочется всего этого совсем, и как я только выдержу эти сорок минут — целый урок в школе или половина пары в университете — когда это было?"},{"kind":"paragraph","text":"Бассейн совершенно пустой в этот раз. Дежурный спасатель (девочка), изогнувшись, сидит за столом и пялится в телефон. На ней голубые джинсы, увеличивающие в объёме и без того крепкие ляжки, футболка с весёленьким логотипом спортивного комплекса и распущенные, как у ундины, волосы цвета подключённой к электричеству лампочки. Подойдя ближе, я втягиваю живот и здороваюсь. Она, не глядя, кивает в ответ. Занята телефоном, видимо, перепиской с парнем, придурком-спортсменом. Её ресницы измазаны тушью, на впалых щеках румянец — как она меня будет спасать в случае, если моё истрёпанное сердце застопорится? Она же подавится тушью и пойдёт на дно под тяжестью вымокших джинсов."},{"kind":"paragraph","text":"Я аккуратно нырнул, но всё равно потянул носом хлорированную воду. В горле запекло, воспалилась слизистая в ноздрях. Окаменев от ненависти и холода, я поплыл брасом, выдыхая под воду и глотая воздух на каждый третий мах правой руки."},{"kind":"paragraph","text":"Я вбираю в себя скукожившуюся мошонку, я сплёвываю под воду вязкую слюну, мешающую дышать как следует."},{"kind":"paragraph","text":"Вскоре я привыкаю и увеличиваю темп; мышцы на спине горят, наполняются силой плечи и ноги. Я стараюсь работать ногами, чтобы сбросить с них лишний жир. Время застыло, и я стараюсь не думать о минутах; пытаюсь представить, что я в море — пьяный и ласковый. Всё равно никто нигде меня не ждёт."},{"kind":"paragraph","text":"Так в тот вечер я плавал, не останавливаясь, около двадцати минут, а потом ушёл под воду, чтобы эффектно развернуться, и вдруг оказался в темноте. Что такое? Неужели я посреди Стикса? Лунный свет, проникающий сверху в окошки, позволяет поверить, что я ещё жив."},{"kind":"paragraph","text":"— Эй! — крикнул я и погрёб к бортику."},{"kind":"paragraph","text":"Нет никого, тишина, и только часы мерцают. Я выполз на кафель, нашарил шлёпки и стал бродить вдоль бассейна."},{"kind":"paragraph","text":"— Инструктор?! Девушка! Что за херня?!"},{"kind":"paragraph","text":"Выделившийся пот выталкивает из пор хлорированную воду. Я бегу в душевую — там тоже темно; щёлкаю выключателем — нет электричества. Направившись к шкафчикам, я поскользнулся и упал, как модель на подиуме, — коленку запекло. Дёргаю дверь — закрыто."},{"kind":"paragraph","text":"— Есть кто?! Что случилось?"},{"kind":"paragraph","text":"Я разогнался, насколько это возможно в шлёпках, и ударил плечом в дверь — куда там! Пару раз крикнув, решил отыскать свой шкафчик, но его было не найти. Ночевать здесь, что ли?"},{"kind":"paragraph","text":"Вернувшись к бассейну, я уселся за стол инструктора и отдышался. Указательный палец прилипает к большому — кровь из коленки. Нашарив пластмассовый свисток с резвой горошиной, я стал свистеть, надеясь, что совпадаю с кодировкой сигнала SOS."},{"kind":"paragraph","text":"Я сижу в темноте, смотрю на чёрное небо через окошко и посвистываю, прижимая ладонью саднящую коленку. Хоть плачь прямо в воду!"},{"kind":"paragraph","text":"Подаю сигнал, матерюсь, выкашливаю капельки хлорированной воды и опять свищу, как придурок. Если сейчас сюда войдёт эта девка, то я подбегу к ней и одним ударом свалю эту тварь в бассейн, вместе с её макияжем. Пусть поплавает, почувствует, что значит быть оставленной."},{"kind":"paragraph","text":"Свищу, вздрагивая от холода, свищу, чувствуя голод, свищу и подумываю отлить в бассейн."},{"kind":"paragraph","text":"Загорается свет. Вбегает она и кричит:"},{"kind":"paragraph","text":"— Я вышла позвонить, а баба Алина подумала, что никого нет, и вырубила электричество!"},{"kind":"paragraph","text":"— И дверь заперла?! — вопрошаю я, свищу и направляюсь к ней."},{"kind":"paragraph","text":"— Да! Она не знала, что тут кто-то есть. Думала, я ушла совсем. Извините!"},{"kind":"paragraph","text":"Я подошёл к ней и замер, не решившись устроить скандал. Что ей сказать? Ударить её? Толкнуть? Шёл, однако, к ней, стараясь казаться грозным. Пугал. Она встала рядом с третьей дорожкой и вытянулась."},{"kind":"paragraph","text":"Я свистнул и сказал:"},{"kind":"paragraph","text":"— Ну и овца ты. Я тут… Ну ладно…"},{"kind":"paragraph","text":"Не сумев подобрать слова, я свистнул сквозь тишину."},{"kind":"paragraph","text":"А что, собственно? Посидел десять минут в темноте и коленку поцарапал. Был один, как всегда — чего тут? Всё в порядке. Но всё равно, случилось нечто унизительное. Ведь я страдал как приговорённый, но не объяснишь. Одиночество в темноте. Со мной каждую ночь такое, и ничего, не умер до сих пор. Живой, вон подумываю, что бы такое сожрать на ужин. А всё-таки что-то есть. Унизительное."},{"kind":"paragraph","text":"— У вас кровь там немножко."},{"kind":"paragraph","text":"— Немножко, да! — соглашаюсь я, судорожно соображая, как действовать. — Вот на, держи — поплавай!"},{"kind":"paragraph","text":"Протяжно свистнув, я запускаю свистком в середину бассейна и слежу за её реакцией."},{"kind":"paragraph","text":"Она прищуривается, чтобы запомнить место падения свистка, переводит удивлённый взгляд на меня и говорит:"},{"kind":"paragraph","text":"— Зачем вы? Достаньте, пожалуйста."},{"kind":"paragraph","text":"— Сама достанешь."},{"kind":"paragraph","text":"А вдруг разденется и при мне в воду полезет? Я смотрю на её дрожащие губы, чувствую, что её волосы пахнут шампунем, а футболка — дезодорантом."},{"kind":"paragraph","text":"— Мне нельзя в воду, — она опускает глаза. — Сейчас нельзя, временно."},{"kind":"paragraph","text":"Пожав плечами, ухожу в душевую и, невесть что себе вообразив, не прикрываю дверь. Моюсь в слишком горячей воде и смеюсь, сверху рассматривая собственное тело. Отлив гнева компенсируется приливом радости. Жалко только, что она всё равно не почувствует, как страшно мне было, как больно! Непонятно, как это назвать. Даже прочитай она всё это — всё равно не поймёт. Мне же непонятно, какого чёрта она ушла болтать по телефону в рабочее время… И баба Алина эта…"},{"kind":"paragraph","text":"Потом, спустя неделю, мы разговорились с ней, с этой девушкой. Её зовут Лия, ей, как и мне, двадцать пять лет, и она припомнила, что как-то в студенчестве, на какой-то межвузовской конференции, посвящённой воспитанию нравственности у молодёжи, мы сидели совсем рядом и даже болтали. Извинившись, она выписала мне бесплатный абонемент до конца года. Я естественно, извинился за грубость."},{"kind":"paragraph","text":"— Мама позвонила. Срочный звонок. Никогда такого не было, понимаете? Я не могла предположить, что так получится. Извините, пожалуйста."},{"kind":"paragraph","text":"Я отыскал её профиль в социальных сетях и написал небольшое ироничное письмо. Она быстро ответила, точно ждала. Теперь мы иногда гуляем, но не больше. Она не очень мне нравится как женщина, но с ней мне легко. Легко потому, что её опыт меньше моего раз в десять. А ещё она верит в то, что завтрашний день будет лучше нынешнего. Ей сразу и резко не понравился мой пессимизм (я так его не называю)."},{"kind":"paragraph","text":"Лия ортодоксальная протестантка, поэтому ей запрещено распивать вино на скамейке. Её не пригласишь домой, и лезть со слюнявыми поцелуями бесполезно. В строго определённое время она отправляется спать и хмурится, когда я говорю что-то грубое. Однажды, очень к месту, я сказал при ней главный русский мат, и она сделалась неразговорчивой до конца вечера. Я наблюдаю со стороны, как у нас с ней ничего не получается. Разговоры всё реже и короче. Общих тем, которых, казалось, уйма, теперь почти нет. Мне не нравится её подбородок. Слишком мужской. Она спросила, не жмут ли мне джинсы и занимаюсь ли я каким-то спортом, кроме бассейна. Прежде она отмечала, что я вполне атлетичен. Я наблюдатель сам за собой. Подсматриваю то, как не подхожу другой особи. Женское разочарование. Вот ещё немножко, и всё."},{"kind":"paragraph","text":"Это был конец декабря; мы обошли Белгород по кругу: стартовали от «штанов» и дальше по Сумской, в сторону Октябрьского суда, а потом направо по Чичерина, вдоль дороги до самой Богданки через Мичурина. Снега выпало мало, был штиль, поэтому мы легко преодолели это расстояние. Она всё молчала и кивала, а я рассказывал о своей летней поездке в Санкт-Петербург. Лия не слушала. Было понятно, что свидание у нас последнее. А ещё — что нужно сменить бассейн."},{"kind":"paragraph","text":"Скоро Новый год. Я его встречу один. Без жирной еды и алкоголя. У монитора ноутбука — там какой-нибудь фильм. Из воды на сушу, из света в тень. И обратно. Год за годом. Пусть будет так."}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
