INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd3-russkaya-skazka',
  'Русская сказка',
  (SELECT id FROM "Authors" WHERE name = 'Николай Старообрядцев' ORDER BY id LIMIT 1),
  'mrd3/mrd3-russkaya-skazka.jpg',
  'data:image/jpeg;base64,',
  1580,
  1186,
  'В деревне стояла изба. В избе жили два человека — отец и мать. Ещё у них был сын — совсем маленький. Но маленьким он был только ростом, а с виду — древний старик. Из-за этого люди думали, что он — отец отца, а сами отец ',
  '[{"kind":"image","path":"mrd3/mrd3-russkaya-skazka.jpg","caption":null},{"kind":"paragraph","text":"В деревне стояла изба. В избе жили два человека — отец и мать. Ещё у них был сын — совсем маленький. Но маленьким он был только ростом, а с виду — древний старик. Из-за этого люди думали, что он — отец отца, а сами отец с матерью — его дети. Слух об этом разнёсся повсюду, а когда он вернулся обратно, ему поверили уже все, даже отец с матерью. Они стали называть своего сына отцом, а он их — детьми. И когда в деревню пришла смерть, всем было ясно, что с нею пойдёт сын."},{"kind":"paragraph","text":"Мать с отцом вымыли сына в бане, обрядили его в белые одежды, дали кусок хлеба в котомке, перекрестили и отправили в путь-дорожку, а сами легли на печь и стали отдыхать."},{"kind":"paragraph","text":"Пошёл сын на кладбище. Когда он пришёл, была уже ночь и смерть спала. Не стал он её будить, а съел кусок хлеба, забрался в могилу и уснул. И так сладко спалось ему в могиле, что проспал он три дня и три ночи, а когда проснулся и вылез, то увидел, что смерть ушла."},{"kind":"paragraph","text":"Сын проголодался, но на кладбище есть было нечего, поэтому он пошёл обратно в свою деревню — авось, отец с матерью накормят. Пришёл он домой и видит — сидят отец с матерью за столом и горюют. Спрашивает у них сын:"},{"kind":"paragraph","text":"— Что случилось, дети мои?"},{"kind":"paragraph","text":"Отвечают ему родители:"},{"kind":"paragraph","text":"— Приходила к нам смерть. Говорила, что пропал наш отец и теперь она заберёт нас вместо него."},{"kind":"paragraph","text":"— Что же отвечали вы ей?"},{"kind":"paragraph","text":"— Отвечали мы, что привыкли жить на белом свете. Не хотим умирать."},{"kind":"paragraph","text":"— И что же, помиловала вас смерть?"},{"kind":"paragraph","text":"— Помиловала, отец. Да только одно условие поставила."},{"kind":"paragraph","text":"— Какое же условие, дети мои?"},{"kind":"paragraph","text":"— Пообещали мы родить сына и ей отдать."},{"kind":"paragraph","text":"— И что же, согласилась ли смерть?"},{"kind":"paragraph","text":"— Согласилась, отец. Да только одно условие поставила."},{"kind":"paragraph","text":"— Какое же условие, дети мои?"},{"kind":"paragraph","text":"— Нужно нам сына родить сегодня к вечеру."},{"kind":"paragraph","text":"Сказав такие слова, горько плакали отец с матерью. Не ведали они, как можно за один день сына родить."},{"kind":"paragraph","text":"Подумал сын и так отвечал родителям своим:"},{"kind":"paragraph","text":"— Не кручиньтесь, дети мои. Знаю, как помочь вам. Я у вас маленький. Заберусь я к матери под подол и спрячусь там. Когда смерть придёт, тряхнёт мать подолом, я и выпаду. Увидит смерть, что я родился, и заберёт меня."},{"kind":"paragraph","text":"Обрадовались отец с матерью, что сын у них такой смышлёный вырос. И порешили сделать, как он сказал."},{"kind":"paragraph","text":"Пришла вечером смерть. Подошла к отцу с матерью и спрашивает:"},{"kind":"paragraph","text":"— Где же сын, которого обещали мне?"},{"kind":"paragraph","text":"Возликовала мать, что сейчас ей спасение будет, да так сильно подолом тряхнула, что покатился сын по полу кубарем и через творило улетел в подполье. Рассердилась смерть, что не дали ей сына — и забрала отца с матерью. Стали они мёртвые. Увидел это сын, перепугался и решил никогда уже не вылезать из подполья. Так всю жизнь там и прожил."}]'::jsonb,
  '2022-12-30T12:00:00.000Z'
)
